INSERT INTO `faqs` VALUES (1, 1, 'ที่อยู่คณะวิทยาศาสตร์', 'ที่อยู่, คณะวิทยาศาสตร์', 'คณะวิทยาศาสตร์,ที่อยู่,ที่ตั้ง,ที่ตั้งคณะ', 'ชื่อสถานที่ :  คณะวิทยาศาสตร์ มหาวิทยาลัยขอนแก่น / Faculty of Science, Khon Kaen University', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (2, 1, 'ที่อยู่', 'ที่อยู่', '', 'ที่ตั้ง: เลขที่ คณะวิทยาศาสตร์ มหาวิทยาลัยขอนแก่น, 123 ม.16 ถ.มิตรภาพ ต.ในเมือง อ.เมือง จ.ขอนแก่น 40002', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (3, 1, 'พิกัดแผนที่ (Google map)', 'พิกัดแผนที่, Google map', 'แผนที่', ': https://kku.world/0gg2lu', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (4, 1, 'เบอร์โทร,email', 'เบอร์โทร, อีเมล', 'โทร,เบอร์โทร', '043-009-700 (และต่อหมายเลขหน่วยงานภายใน)  อีเมล: sc.inbox@kku.ac.th', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (5, 1, 'วันและเวลาเปิด-ปิด:', 'วันเปิด-ปิด, เวลาเปิด-ปิด', 'วันเวลาเปิด,วันเวลาปิด', 'วันและเวลาเปิด-ปิด: เปิดทุกวัน เวลา 08.30 – 16.30 น. (หยุดเสาร์-อาทิตย์ และวันหยุดนักขัตฤกษ์)', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (6, 2, 'รอบที่ 1.1 Portfolio มีโครงการอะไรที่รับเด็กซิ่วบ้าง?', 'รอบ Portfolio, โครงการ, เด็กซิ่ว', 'Portfolio,เด็กซิ่ว,เข้าเรียนรอบPortfolio,โครงการรับเด็กซิ่ว,TCAS1,Portfolio', 'รับเฉพาะโครงการผู้มีศักยภาพสูง กรณีเป็นผู้สำเร็จการศึกษาชั้นมัธยมศึกษาปีที่ 6 และมีผลการเรียน 6 ภาคการศึกษา', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (7, 2, 'รอบที่ 1.1 Portfolio รับกี่โครงการ อะไรบ้าง?', 'รอบ Portfolio, โครงการ,รับกี่โครงการ', '', 'รับทั้งหมด   โครงการ 1) โครงการสัปดาห์วิทยาศาสตร์แห่งชาติ 2) โครงการผู้มีศักยภาพสูง (กรณีเป็นนักเรียนที่กำลังศึกษามัธยมศึกษาปีที่ 6) 3) โครงการ วมว. 4) โครงการ สอวน. 5) โครงการเด็กดีมีที่เรียน', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (8, 2, 'การรับโครงการสัปดาห์วิทยาศาสตร์แห่งชาติ ใช้ประกาศนียบัตรที่เข้าร่วมกิจกรรมสัปดาห์วิทยาศาสตร์ของโรงเรียน หรือการเข้าร่วมกิจกรรมสัปดาห์วิทยาศาสตร์ของมหาวิทยาลัยอื่นได้หรือไม่?', 'โครงการสัปดาห์วิทยาศาสตร์แห่งชาติ, ประกาศนียบัตร, กิจกรรมสัปดาห์วิทยาศาสตร์', 'สัปดาห์วิทยาศาสตร์,TCAS1,Portfolio', 'หลักฐานที่ใช้แนบจะต้องเป็นประกาศนียบัตรที่ได้รับรางวัล (รางวัลที่ 1, 2, 3 หรือชมเชย) ในการเข้าร่วมการแข่งขันในกิจกรรมสัปดาห์วิทยาศาสตร์แห่งชาติ ที่จัดโดยคณะวิทยาศาสตร์ มหาวิทยาลัยขอนแก่น หรือ วิทยาลัยการคอมพิวเตอร์ มหาวิทยาลัยขอนแก่น เท่านั้น', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (9, 2, 'การสมัคร TCAS รอบที่ 1.2 โครงการ พสวท. เปิดรับสมัครเมื่อไหร่?', 'TCAS, รอบ 1.2,พสวท., เปิดรับสมัคร,ปิดรับสมัคร', 'พสวท. ,สควค.,TCAS1,Portfolio', 'โครงการ พสวท. เปิดรับรอบ 1.2 ค่ะ ช่วงเวลารับสมัคร ระหว่างวันที่ 20-25 มกราคม 2569 ค่ะ รอติดตามข่าวสารการสมัคร ได้ที่ https://admissions.kku.ac.th/ ค่ะ', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (10, 2, 'การสมัคร TCAS รอบที่ 1.2 โครงการ สควค. เปิดรับสมัครเมื่อไหร่?', 'TCAS, รอบ 1.2,สควค.,เปิดรับสมัคร,ปิดรับสมัคร', '', 'โครงการ สควค. มข. เปิดรับรอบ 1.2 ค่ะ ช่วงเวลารับสมัคร ระหว่างวันที่ 20-25 มกราคม 2569 ค่ะ รอติดตามข่าวสารการสมัคร ได้ที่ https://admissions.kku.ac.th/ ค่ะ', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (11, 2, 'ถ้ายืนยันสิทธิ์คัดกรองในรอบที่ 1.1 ไปแล้วสามารถสมัครโครงการ พสวท. ในรอบที่ 1.2 ได้ไหม?', 'พสวท.,ยืนยันสิทธิ', '', 'หากยืนยันสิทธิ์คัดกรองภายใน มข. ในรอบที่ 1.1 แล้ว จะไม่สามารถสมัคร TCAS รอบที่ 1.2 ในโครงการ พสวท. ได้', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (12, 2, 'ถ้ายืนยันสิทธิ์คัดกรองในรอบที่ 1.1 ไปแล้วสามารถสมัครโครงการ สควค. ในรอบที่ 1.2 ได้ไหม?', 'สควค.,ยืนยันสิทธิ', '', 'หากยืนยันสิทธิ์คัดกรองภายใน มข. ในรอบที่ 1.1 แล้ว จะไม่สามารถสมัคร TCAS รอบที่ 1.2 ในโครงการ สควค. ได้', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (13, 2, 'โครงการ สควค. รอบที่ 1.2 จะต้องผ่านสัมภาษณ์จาก รอบที่ 1.1 ก่อนจึงจะสมัครได้ใช่หรือไม่?', 'โครงการ สควค., รอบ 1.2, สัมภาษณ์, รอบ 1.1', 'สควค.,TCAS1,Portfolio', 'การสมัครรอบที่ 1.2 โครงการ สควค. แยกรับเฉพาะโครงการ สควค. ผู้สมัครสามารถสมัครในรอบที่ 1.2 ได้โดยตรง เนื่องจากไม่ได้รับบุคคลที่ผ่านรอบที่ 1.1 ก่อน', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (14, 2, 'หากมีรายชื่อมีสิทธิ์เข้าสอบสัมภาษณ์ จะต้องนำ Portfolio ไปด้วยหรือไม่', 'รายชื่อ, สอบสัมภาษณ์, Portfolio', 'Portfolio,Portfolio,มีสิทธิ์เข้าสอบสัมภาษณ์', 'ในประกาศรับสมัคร ระบุให้นำ Portfolio ไปด้วยในวันสัมภาษณ์', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (15, 2, 'ถ้ามีรายชื่อเป็นผู้มีสิทธิ์เข้าสอบสัมภาษณ์ จะต้องนำแฟ้มสะสมงาน (Portfolio) ไปด้วยหรือไม่?', 'รายชื่อ, สอบสัมภาษณ์, แฟ้มสะสมงาน, Portfolio', 'สัมภาษณ์,TCAS2,Quota', 'หากการนำแฟ้มสะสมงาน (Portfolio) มาประกอบการสอบสัมภาษณ์ด้วย ก็จะเป็นผลดีต่อผู้มีสิทธิ์เข้าสัมภาษณ์ หรือหากไม่นำมา ก็ไม่ถูกตัดสิทธิ์ใด ๆ', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (16, 2, 'สาขาวิชาชีววิทยา รูปแบบที่ 1 และรูปแบบที่ 2 แตกต่างกันอย่างไร?', 'สาขาวิชาชีววิทยา, รูปแบบที่ 1, รูปแบบที่ 2', 'ชีววิทยา,TCAS3,Admission', 'สาขาวิชาชีววิทยา รูปแบบที่ 1 คือ สายวิทย์-คณิตฯ / สาขาวิชาชีววิทยา รูปแบบที่ 2 คือ สายศิลป์', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (17, 2, 'คณะวิทยาศาสตร์จะต้องตรวจร่างกายและส่งเอกสารการตรวจร่างกายหรือไม่?', 'ตรวจร่างกาย, เอกสารการตรวจร่างกาย', 'ตรวจร่างกาย,TCAS1,Portfolio', 'คณะวิทยาศาสตร์ไม่ได้ให้ผู้สมัครตรวจร่างกาย และไม่ต้องใช้เอกสารการตรวจร่างกายในการประกอบการสอบสัมภาษณ์', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (18, 2, 'ในการสัมภาษณ์คณะวิทยาศาสตร์ มีเข้ากลุ่มไลน์ให้เข้าหรือไม่?', 'สัมภาษณ์, คณะวิทยาศาสตร์, กลุ่มไลน์', 'สัมภาษณ์,TCAS1-2-3', 'คณะวิทยาศาสตร์ไม่มีการเชิญให้ผู้มีสิทธิ์สอบสัมภาษณ์เข้ากลุ่มไลน์ แต่จะเป็นการส่งอีเมลแจ้งรายละเอียดเท่านั้น', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (19, 2, 'การรายงานตัวต้องเข้าไปรายงานตัวที่มหาวิทยาลัยหรือไม่?', 'รายงานตัว, มหาวิทยาลัย', 'รายงานตัว,TCAS1-2-3', 'เป็นการรายงานตัวออนไลน์ ไม่ต้องเดินทางมาที่มหาวิทยาลัย  ลิงค์ : https://reg.kku.ac.th', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (20, 2, 'ถ้ารายงานตัวในระบบแล้วแต่ยังไม่ชำระค่าธรรมเนียมการศึกษา จะมีสิทธิ์ได้รับอีเมลประจำตัวนักศึกษาของมหาวิทยาลัยขอนแก่นหรือไม่?', 'รายงานตัว, ค่าธรรมเนียมการศึกษา, อีเมลประจำตัวนักศึกษา', 'รายงานตัว,TCAS1-2-3,ยังไม่ชำระค่าธรรมเนียม,', 'จะยังไม่ได้รับอีเมลประจำตัวนักศึกษา จนกว่าจะชำระค่าธรรมเนียมการศึกษาภายในระยะเวลาที่มหาวิทยาลัยกำหนด', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (21, 2, 'โครงการ สควค. ของ ม.ขอนแก่น', 'โครงการ สควค., ม.ขอนแก่น, ปิดรับ', 'สควค.โครงการ สควค,สควค.ปิดแล้ว,สควค.เปิดเมื่อไหร่', 'สควค. มข. เปิดรับรอบ 1.2 ค่ะ ช่วงเวลารับสมัคร 20-25 มกราคม 2569 ค่ะ รอติดตามข่าวสารการสมัคร ได้ที่ https://admissions.kku.ac.th/ ค่ะ\nลิงค์ : https://admissions.kku.ac.th/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (22, 2, 'สามารถสมัครทั้งโครงการเด็กดีมีที่เรียน และโครงการผู้มูศักยภาพสูงได้ไหมครับ หรือต้องเลือกสมัครอันใดอันหนึ่ง', 'โครงการเด็กดีมีที่เรียน, โครงการผู้มีศักยภาพสูง', 'โครงการเด็กดี,เลือกสมัคร', 'สมัครได้ทั้ง 2 โครงการค่ะ ไม่ผิดเงื่อนไข', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (23, 2, 'ถ้าผมผ่านการสัมภาษณ์ตัวจริงในรอบ 1.1 ผมสามารถยื่นทุน สควค. อีกได้ไหม', 'สัมภาษณ์, รอบ 1.1, ทุน สควค.', 'ผ่านการสัมภาษณ์ตัวจริง,ผ่านการสัมภาษณ์ตัวจริง,ทุน สควค.', 'ถ้าหากรอบ 1.1 ผ่านสัมภาษณ์ แล้วยืนยันสิทธิ์คัดกรอง มข. แล้ว จะไม่สามารถสมัครรอบ 1.2 ได้', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (24, 2, 'โครงการมากกว่า 1 ปริญญา', 'มากกว่า 1 ปริญญา, ปริญญาที่สอง, เรียนสองปริญญา, 1 ปริญญา', 'รมากกว่า1ปริญญา,1ปริญญา', 'โครงการมากกว่า 1 ปริญญา สามารถโทรสอบถามได้ที่ 084-6001149 หรือ 091-4210065 ในวัน-เวลา ราชการได้', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (25, 3, 'ลงทะเบียนมากกว่ากำหนด ต้องแนบอะไร', 'ลงทะเบียน, มากกว่ากำหนด, แนบ', 'ลงทะเบียนมากกว่ากำหนด  ลงทะเบียนมากกว่า 22 หน่วยกิต', 'แนบแผนการศึกษาจากหลักสูตร ศึกษาข้อมูลตามรายหลักสูตรได้ที่  https://sc.kku.ac.th/program-bachelor/ หรือตารางการเรียนรายวิชาที่ระบุวันเวลเรียน เวลาสอบที่ผ่านความเห็นจากอาจารย์ที่ปรึกษา แต่ไม่นำผลการลงทะเบียนจาก reg มาแนบ\n\nhttps://sc.kku.ac.th/program-bachelor/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (26, 3, 'ลงทะเบียนเรียนซ้ำกรณีครบหลักสูตร (เกรด C ขึ้นไปแต่ต่ำกว่า A) มีเงื่อนไขอย่างไร', 'ลงทะเบียนเรียนซ้ำ, ครบหลักสูตร, เกรด C, เงื่อนไข', 'ลงทะเบียนเรียนซ้ำ', 'นักศึกษาต้องเรียนครบตามหลักสูตรกำหนดแล้วเท่านั้น แต่ยังไม่ผ่านเกณฑ์ ถ้ายังมีวิชาเรียนในเทอมสุดท้ายจะถือว่ายังไม่ครบตามหลักสูตร เช่นในเทอมสุดท้ายลงเรียนวิชาโครงงานการวิจัย จะยังไม่สามารถดำเนินการลงทะเบียนเรียนซ้ำได้ และขอให้ส่งไฟล์ตรวจสอบจบที่ผ่านอาจารย์ปรึกษา และ/หรือหัวหน้าสาขาวิชาตรวจสอบการเรียนครบตามหลักสูตร (ดาวน์โหลดแบบฟอร์มตรวจสอบการสำเร็จกการศึกษา ได้ที่ https://sc.kku.ac.th/student/) ส่งที่งานบริการการศึกษาและพัฒนานักศึกษา คุณฐิติมา หรือส่งที่ thitimap@kku.ac.th\n\nhttps://sc.kku.ac.th/student/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (27, 3, 'สามารถลงทะเบียนเรียนต่อภาคการศึกษาได้น้อยสุดกี่หน่วยกิต', 'ลงทะเบียนเรียน, น้อยสุด, หน่วยกิต', 'ลงทะเบียนเรียนน้อย', '1 หน่วยกิต\nhttps://reg-mirror.kku.ac.th/registrar/home.asp?avs=46010.4165509259', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (28, 3, 'ลงทะเบียนน้อยชำระค่าธรรมเนียมการศึกษาเท่าไหร่', 'ลงทะเบียนน้อย, ค่าธรรมเนียมการศึกษา', 'ค่าธรรรมเนียมการศึกษาลงน้อย', 'รหัสประจำตัวน้อยกว่า 68 ชำระ 12,000 บาท/ภาคการศึกษา สำหรับนักศึกษารหัสประจำตัวขึ้นต้น 68 ในภาคการศึกษาสุดท้าย ชำระ 8,000 บาท/ภาคการศึกษา', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (29, 3, 'สอบถามค่าธรรมเนียมการศึกษา', 'ค่าธรรมเนียมการศึกษา', 'ค่าธรรมเนียมการศึกษา', 'สำหรับนักศึกษาที่มีรหัสประจำตัวน้อยกว่า 62 ชำระค่าธรรมเนียมการศึกษา 12,000 บาท/เทอม รหัสประจำตัวขึ้นต้น 68 เป็นต้นไป ค่าธรรมเนียมการศึกษา 16,000 บาท/เทอม  \nhttps://apps.admissions.kku.ac.th/web/Tuitionfee/Program/2', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (30, 3, 'แนวปฎิบัติกรณีการผ่อนผันค่าธรรมเนียมการศึกษา', 'ผ่อนผัน, ค่าธรรมเนียมการศึกษา', 'การผ่อนผันค่าธรรมเนียม', 'สำหรับนักศึกษาปี 2 ขึ้นไป สามารถยื่นคำร้องออนไลน์ผ่าน REQ.KKU.AC.TH  ซึ่งนักศึกษาต้องลงทะเบียนและยืนยัน\nผลการลงทะเบียนให้เรียบร้อยก่อน (หากได้รับอนุมัติให้ผ่อนผันฯ จะไม่สามารถดำเนินการเปลี่ยนแปลง\nผลการลงทะเบียนเรียนในระบบได้) โดยมีเอกสารประกอบและรายละเอียดการพิจารณาดังนี้\n        1. หนังสือค้ำประกัน (พร้อมกรอกรายละเอียดให้เรียบร้อย โดยมีลายเซ็นผู้ค้ำประกัน 1 คน และพยาน 2 คน  ข้อควรระวัง การให้ผู้คำ้ประกันที่มีสามีหรือภรรยา สามีหรือภรรยาของผู็ค้ำ้ประกันไม่สามารถเป็นพยานได้)\n        2. สำเนาบัตรผู้ค้ำประกัน (ต้องไม่หมดอายุ) \n        3. ค่าคะแนนเฉลี่ยสะสม (GPA.) ต้องอยู่ในเกณฑ์ที่กำหนดดังนี้\n            - ระดับปริญญาตรีต้องไม่ต่ำกว่า 1.80\n            - ระดับบัณฑิตศึกษาไม่ต่ำกว่า 3.00\n        4. ระยะเวลาในการผ่อนผัน\n            - ระดับปริญญาตรี\n              ไม่เกินก่อนสอบกลางภาค 1 สัปดาห์ (ตามปฏิทินการศึกษา)\n            - ระดับบัณฑิตศึกษา\n              ไม่เกินวันสุดท้ายของการขอถอนรายวิชาโดยได้สัญลักษณ์ W (ตามปฏิทินการศึกษา)\n        5. การชำระจะต้องชำระเต็มจำนวนไม่มีการแบ่งชำระ\n\nhttps://req.kku.ac.th/officer/inbox', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (31, 3, 'การผ่อนผันค่าธรรมเนียมการศึกษา สำหรับนักศึกษาชั้นปีที่ 1', 'ผ่อนผัน, ค่าธรรมเนียมการศึกษา, ชั้นปีที่ 1', 'ผ่อนผัน ปี 1', 'สามารถติดต่องานบริการการศึกษาและพัฒนานักศึกษา เพื่อสอบถามข้อมูล ได้ที่เบอร์โทร. 084-6001149, 091-4210065 (ในวันเวลาราชการ)', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (32, 3, 'ขอลงทะเบียนในรายวิชาที่ไม่ได้สำรองที่นั่งทำอย่างไร', 'ลงทะเบียน, รายวิชา, สำรองที่นั่ง', 'ไม่ได้สำรองที่นั่ง', 'ให้นักศึกษาตรวจสอบว่าตนเองได้ลงทะเบียนเรียนตรงตามที่หลักสูตรกำหนดหรือไม่\n- กรณีที่ลงทะเบียนตามหลักสูตรแล้ว : ให้นำรหัสนักศึกษา แจ้งได้ที่งานบริการการศึกษา สามารถติดต่อได้ที่ : งานบริการการศึกษาและพัฒนานักศึกษา, อาคาร SC.06 (ชั้น1) คณะวิทยาศาสตร์ มหาวิทยาลัยขอนแก่น\n- กรณีที่ไม่ได้ลงทะเบียนตามหลักสูตร : ให้สำรองที่นั่ง โดยกรอกแบบฟอร์มทางเว็ปไซต์ https://req.kku.ac.th/\"', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (33, 3, 'ขอลงทะเบียนเกิน 22 หน่วยกิตได้หรือไม่', 'ลงทะเบียนเกิน, หน่วยกิต', 'ลงทะเบียนเรียนเกิน', 'ได้ แต่ต้องไม่เกิน 25 หน่วยกิต ติดต่อกับอาจารย์ที่ปรึกษาเพื่อได้รับอนุญาต โดยกรอกแบบฟอร์มทางเว็ปไซต์เพื่อขอลงทะเบียนเรียนเกินได้ที่ https://req.kku.ac.th/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (34, 3, 'ขอลงทะเบียนเรียนซ้ำได้เมื่อไร', 'ลงทะเบียนเรียนซ้ำ', 'ลงทะเบียนเรียนซ้ำ', 'สามารถลงซ้ำได้ทุกภาคการศึกษา โดยต้องลงทะเบียนเรียนรายวิชาที่ได้ค่าคะแนนไม่สูงกว่า D+ \nซึ่งการคำนวณเกรดสะสมจะนำเกรดที่ดีที่สุดในวิชาที่ลงทะเบียนซ้ำมาคำนวณ โดยสามารถยื่นเรื่องลงทะเบียนเรียนซ้ำได้ที่ https://req.kku.ac.th/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (35, 3, 'ค่าธรรมเนียมภาคการศึกษาพิเศษ', 'ค่าธรรมเนียม, ภาคการศึกษาพิเศษ', 'ค่าธรรมเนียมภาคการศึกษาพิเศษ', 'สำหรับนักศึกษารหัสประจำตัวน้อยกว่า 68 ชำระ 6,000 บาท รหัสประจำตัวขึ้นต้น 68  ชำระ 8,000 บาท\n\nhttp://reg.kku.ac.th', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (36, 3, 'เข้าไปดูในเว็บแล้วมีแต่โครงการห้องเรียนพสวท.\nโครงการผู้มีศักยภาพสูง\nโครงการสควค.\nโครงการสัปดาห์วิทยาศาสตร์แห่งชาติ\nแล้วโครงการเด็กดีมีที่เรียนของคณะวิทยาศาสตร์ประกาศรับสมัครในไหนหรอคะ', 'โครงการห้องเรียนพสวท., โครงการผู้มีศักยภาพสูง, โครงการสควค., โครงการสัปดาห์วิทยาศาสตร์แห่งชาติ, โครงการเด็กดีมีที่เรียน', 'โครงการห้องเรียนพสวท.,โครงการผู้มีศักยภาพสูง,สควค.,สัปดาห์วิทยาศาสตร์,โครงการเด็กดีมีที่เรียน,รับสมัครเข้าเรียน', 'https://drive.google.com/drive/folders/1Yb44qMnLFRosYffQ2jOVVvzLOMvlZrrz', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (37, 3, 'เริ่มนับค่าปรับการลงทะเบียนเรียนช้าคือเมื่อไหร่', 'ค่าปรับ, ลงทะเบียนเรียนช้า', 'ค่าปรับลงทะเบียนเรียนช้า', 'วันลงทะเบียนวิชาเรียน ล่าช้าผ่านเว็บ ไซต์\nhttp://reg.kku.ac.th หรือ วันเพิ่มวิชาเรียน\nผ่านเว็บไซต์ นับทุกวันทำการ แต่ไม่เกิน 3,00 บาท/ภาคการศึกษา\n1. http://reg.kku.ac.th    2. https://req.kku.ac.th/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (38, 4, 'ถ้าไม่ได้เข้าสอบทำอย่างไร', 'เข้าสอบ, ไม่ได้เข้าสอบ, ไม่ได้สอบ, ขาดสอบ, มาสอบไม่ได้, ทำไงบ้าง, ขั้นตอนการลาสอบ', 'ไม่ได้เข้าสอบ, ไม่ได้สอบ, ขาดสอบ, มาสอบไม่ได้, ทำไงบ้าง, ขั้นตอนการลาสอบ', 'นักศึกษาต้องแจ้งให้ประธานคณะกรรมการสอบทราบทันทีถึง สาเหตุที่ไม่สามารถเข้าสอบได้\nพร้อมที่อยู่ที่คณะกรรมการสอบสามารถติดต่อได้ คณะกรรมการสอบจะเป็นผู้พิจารณาว่าเป็น\nเหตุสุดวิสัยตามกล่าวอ้างของนักศึกษาหรือไม่                                                                                                \nหรือทำตามข้อเเนะนำต่อไปนี้ หรือทำตามข้อเเนะนำต่อไปนี้\n1.1 นักศึกษาต้องแจ้งให้ประธานคณะกรรมการสอบทราบทันทีถึงเหตุที่ไม่สามารถเข้าสอบได้ พร้อมที่อยู่ที่คณะกรรมการสอบสามารถติดต่อได้ คณะกรรมการสอบจะเป็นผู้พิจารณาว่าเป็น เหตุสุดวิสัยตามกล่าวอ้างของนักศึกษาหรือไม่ \n1.2 นักศึกษาอาจจะเข้าสอบได้ภายในวันเดียวกันกับที่ขาดสอบรายวิชาหนึ่งรายวิชาใด เมื่อคณะกรรมการสอบพิจารณาแล้วมีความเห็นว่าเป็นเหตุสุดวิสัย ทั้งนี้ประธานคณะกรรมการสอบจะแจ้งให้ นักศึกษาทราบกำหนดเวลาและสถานที่สอบ \n1.3 ในกรณีที่ประธานคณะกรรมการสอบพิจารณาแล้ว เห็นว่าไม่สามารถจัดให้นักศึกษาเข้าสอบได้ ภายในวันเดียวกับที่ขาดสอบรายวิชานั้นๆ นักศึกษาจะต้องปฏิบัติดังนี้ \n1.3.1 กรณีลงทะเบียนเรียนรายวิชาในคณะที่นักศึกษาสังกัดอยู่ให้นักศึกษายื่นคำร้องต่อ คณะบดีผ่านอาจารย์ที่ปรึกษาเพื่อพิจารณาแจ้งให้อาจารย์ประจำวิชาดำเนินการสอบชดเชย \n1.3.2 กรณีลงทะเบียนเรียนรายวิชานอกคณะที่นักศึกษาสังกัดอยู่ให้นักศึกษายื่นคําร้องต่อ คณบดีผ่านอาจารย์ที่ปรึกษาเพื่อพิจารณาแจ้งให้คณะที่อาจารย์ประจำวิชาสังกัดดําเนินการสอบชดเชย\nดาวน์โหลดคำร้องขอเลื่อนสอบได้ที่ https://e.sc.kku.ac.th/formonline/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (39, 4, 'ขอเลื่อนสอบทำอย่างไร', 'เลื่อนสอบ', 'ขอเลื่อนสอบ', 'กรณีที่นักศึกษาไม่สามารถเข้าสอบเพราะมีเหตุสุดวิสัย ขอให้ดำเนินการดังนี้ \n1. ดาวน์โหลดคำร้องขอเลื่อนสอบ ได้ที่ https://e.sc.kku.ac.th/formonline/\n2. กรอกข้อมูลให้ครบถ้วน \n3. เสนอเอกสารคำร้องและและแนบหลักฐานประกอบการพิจารณา โดยผ่านผู้เกี่ยวข้องดังนี้\n    3.1 อาจารย์ที่ปรึกษาทั่วไป \n    3.2 เสนอหัวหน้าสาขาวิชา\n    3.3 เสนออาจารย์ประจำวิชา\n4. ยื่นคำร้องที่งานบริการการศึกษาและพัฒนานักศึกษา หรือส่งที่ thitimap@kku.ac.th', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (40, 4, 'การแต่งกายเข้าสอบ/ชุดเข้าสอบ/เข้าสอบต้องใส่ชุดนักศึกษาไหม', 'แต่งกายสอบ,แต่งกายไปสอบ,แต่งกายเข้าสอบ, การแต่งกาย, ยูนิฟอร์ม, ใส่ชุดอะไร, เสื้อนักศึกษา, กางเกงสแล็ค,แต่งตัวไปสอบ,แต่งตัว,ชุดไปสอบ,เข้าสอบต้องใส่', 'การแต่งกายเข้าสอบ/ชุดเข้าสอบ', 'นักศึกษาต้องแต่งกายให้เรียบร้อยถูกต้องตามประกาศของมหาวิทยาลัยขอนแก่น และตามข้อกำหนดของคณะวิทยาศาสตร์ ดังนี้ \n       1.  ชุดที่อนุญาตให้สวมใส่เข้าห้องสอบได้ \n            ให้แต่งกายด้วยชุดเครื่องแบบนักศึกษา หรือชุดสุภาพ ดังนี้ \n            นักศึกษาชาย สวมเสื้อเชิ้ตหรือเสื้อโปโล มีแขน กางเกงขายาว สแลคหรือยีนส์สีเข้ม คลุมข้อเท้า ไม่มีรอยขาด รองเท้าหุ้มส้นไม่เปิดหัวรองเท้า \n            นักศึกษาหญิง สวมเสื้อเชิ้ตหรือเสื้อโปโล มีแขน กระโปรงยาวคลุมเข่า หรือกางเกงขายาว สแลคหรือยีนส์สีเข้ม คลุมข้อเท้า ไม่มีรอยขาด รองเท้าหุ้มส้นหรือรัดส้นไม่เปิดหัวรองเท้า \n        2.  ชุดที่ไม่อนุญาตให้สวมใส่เข้าห้องสอบ (ตามเอกสารแนบท้าย)\n             เสื้อยืดคอกลม คอวี เสื้อไม่มีแขน เสื้อเอวลอย เสื้อรัดรูป เสื้อกีฬาทุกรูปแบบ\n             กางเกงวอร์ม กางเกงยีนส์ขาด กางเกงหัวยืด กางเกงเล กางเกงขาสั้น กระโปรงสั้นเหนือเข่า กระโปรงยีนส์ \n             รองเท้าแตะ รองเท้าไม่หุ้มส้น รองเท้าเปิดหัวรองเท้า\n        3.  หากมีการตีความคำว่าชุดสุภาพ ไม่ตรงกันระหว่างนักศึกษาและกรรมการสอบให้กรรมการสอบอนุญาตให้นักศึกษาเข้าสอบไปก่อน และแจ้งกรรมการอำนวยการสอบเพื่อพิจารณาต่อไป\nรายละเอียด  https://kku.world/4jad08', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (41, 5, 'ขอย้ายคณะ/ย้ายสาขาวิชา เอกสารที่ต้องใช้อะไรบ้าง', 'ย้ายคณะ, ย้ายสาขาวิชา, เอกสาร', 'การขอย้ายคณะ,ย้ายสาขาวิชา,การขอย้ายคณะ,ย้ายสาขาวิชา,ย้ายมหาวิทยาลัย', '1.เป็นนักศึกษาที่มีสิทธิเรียนในคณะต้นสังกัด และต้องมีผลคะแนนการรับเข้าศึกษาไม่น้อยกว่าคะแนนคนสุดท้ายของหลักสูตรที่ขอย้าย \n2.ไม่เคยย้ายคณะเรียนมาก่อน \n3.ศึกษาอยู่ในคณะต้นสังกัดไม่น้อยกว่า 2 ภาคการศึกษาปกติ\n และมีหน่วยกิตสะสมไม่น้อยกว่า 30 หน่วยกิต และมีคะแนนเฉลี่ยสะสมตั้งแต่ 2.00 ขึ้นไป\nรายละเอียด : https://drive.google.com/file/d/1DFq5FHE3XPdCU8icRwq56yckXqS7Skf8/view?usp=drive_link', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (42, 5, 'ขอย้ายมหาวิทยาลัย/สถาบัน เอกสารที่ต้องใช้อะไรบ้าง', 'ย้ายมหาวิทยาลัย, ย้ายสถาบัน, เอกสาร', 'ย้ายมหาวิทยาลัย', '1.หนังสืออนุญาตให้โอนย้ายจากสถาบันเดิม \n2.คําร้องขอย้ายโอนนกศึกษาพร้อมเหตุผล\n3.หนังสือรับรองความประพฤติจากสถาบันเดิม\n4.ใบรายงานผลการศึกษา (TRANSCRIPT)\n5.หนังสือยินยอมของผู้ปกครองให้ย้ายโอน\n6.ใบรับรองแทพย์\n7.รายวิชาและคําอธิบายรายวิชาที่นักศึกษาเคยลงทะเบียนเรียนในสถาบันเดิม\n8.สําเนาทะเบียนบ้าน\n9.สำเนาบัตรประชาชน\n10.สําเนาบัตรประจําตัวนักศึกษาจากสถาบันเดิม\n11.คะแนนผลการสอบวัดความรู้เข้าศึกษาในสถาบันอุดมศึกษา\nรายละเอียด : https://drive.google.com/file/d/1DFq5FHE3XPdCU8icRwq56yckXqS7Skf8/view?usp=drive_link', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (43, 5, 'ขอเทียบโอนรายวิชามีเอกสารที่ต้องใช้อะไรบ้าง', 'เทียบโอนรายวิชา, เอกสาร', 'เทียบโอนหน่วยกิต,การขอเทียบโอนรายวิช,ขอเทียบโอนหน่วยกิต', 'การยื่นคำร้องขอเทียบโอนรายวิชา/ขอเทียบโอนหน่วยกิต ผ่านระบบ REQ เว็บไซต์ https://req.kku.ac.th/\n1. ผลการเรียน (Transcript)\n2. คำอธิบายรายวิชาที่ขอเทียบโอนรายวิชา\n3. ใบเสร็จการจ่ายค่าธรรมเนียมขอเทียบโอนฯ จำนวน 100 บาท\nรายละเอียด : https://drive.google.com/file/d/1l-L6aHE6fX5QdRCba7h2hEHHT4fyxb0T/view?usp=drive_link', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (44, 5, 'ขอเทียบโอนรายวิชาต้องยื่นคำร้องเมื่อไหร่', 'เทียบโอนรายวิชา, ยื่นคำร้อง', '', 'ภายใน 15 วัน นับจากวันเปิดภาคการศึกษาแรกที่เข้าศึกษา\nรายละเอียด : https://drive.google.com/file/d/1l-L6aHE6fX5QdRCba7h2hEHHT4fyxb0T/view?usp=drive_link', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (45, 5, 'ขอเทียบโอนรายวิชายื่นคำร้องได้กี่ครั้ง', 'เทียบโอนรายวิชา, ยื่นคำร้อง', '', 'ยื่นคำร้องได้เพียงครั้งเดียวเท่านั้น\nรายละเอียด : https://drive.google.com/file/d/1l-L6aHE6fX5QdRCba7h2hEHHT4fyxb0T/view?usp=drive_link', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (46, 5, 'ขอเทียบโอนรายวิชาฯรายวิชาที่เทียบโอนต้องมีเกรดเท่าไหร่', 'เทียบโอนรายวิชา, เกรด', '', 'ต้องได้เกรดไม่ต่ำกว่าระดับคะแนนตัวอักษร C ขึ้นไป\nรายละเอียด : https://drive.google.com/file/d/1l-L6aHE6fX5QdRCba7h2hEHHT4fyxb0T/view?usp=drive_link', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (47, 5, 'ขอลากิจ ลาป่วย ในรายวิชาที่เรียนทำอย่างไร', 'ลากิจ, ลาป่วย, รายวิชา', 'ลากิจ,ลาป่วย,การลาเรียน', 'การลาป่วยหากนักศึกษาป่วยด้วยอาการใด ๆ ก็ตามต้องมีใบรับรองแพทย์จากโรงพยาบาลภาครัฐเท่านั้น เพื่อใช้ในการประกอบการลาแล้วนำไปขออนุญาตต่ออาจารย์ผู้สอนในวันแรกที่กลับเข้าชั้นเรียน\nการลากิจ  การลากิจต้องแนบเอกสารที่เกี่ยวข้อง เช่น หนังสือเชิญ หนังสือแต่งตั้ง ภาพถ่าย หรือตั๋วโดยสาร เป็นต้น โดยต้องขอให้อาจารย์ที่ปรึกษาลงนามอนุญาตในการลากิจ แล้วนำไปขออนุญาตต่ออาจารย์ผู้สอนล่วงหน้าอย่างน้อย 1 วัน หากไม่สามารถยื่นใบลาล่วงหน้าได้ ให้ยื่นในวันแรกที่กลับเข้าชั้นเรียน', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (48, 5, 'ขอลาพักการศึกษาดำเนินการอย่างไรบ้าง', 'ลาพักการศึกษา', 'ลาพักการศึกษา', 'เข้าระบบคำร้องออนไลน์ KKUREQ เลือกคำร้องที่ต้องการยื่น\n1. การลาพักการศึกษา ดำเนินการไม่น้อยกว่า 2 สัปดาห์\nก่อนวันแรกของการสอบประจำภาคตามปฏิทินการศึกษาของมหาวิทยาลัย\n2. นักศึกษาจะลาพักการศึกษาได้ครั้งละไม่เกิน 1 ภาคการศึกษาปกติ\n3. นักศึกษาที่ได้รับอนุมัติให้ลาพักการศึกษา \nต้องชำระเงินค่าธรรมเนียม (จำนวน 1,100 บาท)\nเพื่อต่อทะเบียนตามที่มหาวิทยาลัยกำหนด', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (49, 5, 'การต่อทะเบียนนักศึกษาดำเนินการอย่างไรบ้าง', 'ต่อทะเบียนนักศึกษา', 'การต่อทะเบียนนักศึกษา,ขอต่อทะเบียนเป็นนักศึกษา', 'นักศึกษาเข้าระบบคำร้องออนไลน์ \nHTTPS://REQ.KKU.AC.TH เลือกคำร้อง\nการต่อทะเบียนนักศึกษา\n1. แบบฟอร์มตรวจสอบจบต้องการคำนวณค่าคะแนนมาพร้อม \nและอาจารย์ที่ปรึกษา และหัวหน้าสาขาวิชาลงนามแล้ว \n2. Transcript ใบแสดงผลการเรียน ผ่านระบบออนไลน์ที่\nHTTPS://REG.KKU.AC.TH เลือกขอเอกสารออนไลน์\n3. ไฟล์เอกสารในข้อ 1 และข้อ 2 รวมเป็น 1 ไฟล์ \nพร้อมอัปโหลดผ่านระบบ REQ\n4. เมื่อคำร้องอนุมัติการต่อทะเบียนนักศึกษา จะมีข้อความแจ้ง\nชำระเงินผ่านระบบออนไลน์ QR CODE\n(ชำระภายใน 5 วันทำการ) ภาคการศึกษาละ 1,100 บาท \nส่วนค่าปรับล่าช้าคิดอัตราต่อวัน ๆ ละ 50 บาท \nแต่สูงสุดไม่เกิน 3,000 บาท', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (50, 6, 'เกรดขั้นตํ่าในการสําเร็จการศึกษาคือเท่าไร', 'เกรดขั้นต่ำ, สำเร็จการศึกษา', 'การสำเร็จการศึกษา', 'เป็นไปตามระเบียบมหาวิทยาลัยขอนแก่น ว่าด้วยการศึกษาขั้นปริญญาตรี พ.ศ. 2565 ข้อ 36 การสําเร็จการศึกษา โดยมีรายละเอียดดังนี้\n1) ต้องสอบผ่านรายวิชาครบตามหลักสูตร\n2) เกรดเฉลี่ยสะสมตลอดหลักสูตรไม่ตํ่ากว่า 2.00 และเกรดเฉลี่ยในรายวิชาที่สาขากำหนดไม่ตํ่ากว่า 2.00\n3) ผ่านการสอบสมรรถนะฉลาดทางดิจิทัล สำหรับนักศึกษา (KKU DQ) และปรากฎผลการเรียนรายวิชา 000160 เป็น S\n4) มีผลสอบภาษาอังกฤษของสถาบันภาษา (Kept Exit) หรือยื่นคะแนนสอบมาตรฐานภาษาอังกฤษ ได้แก่ TOFEL, IELTS, TOEIC\nรายละเอียด : https://drive.google.com/file/d/1LLHm5vg0nObuZpQ5g7WrXYKnXYoExSQD/view?usp=drive_link', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (51, 6, 'หากต้องการเกียรตินิยมต้องได้เกรดเฉลี่ยเท่าไร', 'เกียรตินิยม, เกรดเฉลี่ย', 'เกียรตินิยม,การได้รับเกียรตินิยม', 'ปริญญาเกียรตินิยมแบ่งได้ดังนี้\n1. ปริญญาเกียรตินิยมอันดับหนึ่ง ให้กับผู้สำเร็จการศึกษาชั้นปริญญาตรีที่ได้รับคะแนนเฉลี่ย สะสมไม่ต่ำกว่า3.60\n2. ปริญญาเกียรตินิยมอันดับสอง ให้กับผู้สำเร็จการศึกษาชั้นปริญญาตรีที่ได้รับคะแนนเฉลี่ย สะสมไม่ต่ำกว่า3.25 \nแต่ต่ำกว่า 3.60\nการคิดคะแนนเฉลี่ยสะสมเพื่อรับปริญญาเกียรตินิยมตามวรรคหนึ่ง ไม่ให้นำระดับคะแนนส่วนที่เป็นการลงทะเบียนเรียนซ้ำเพื่อเปลี่ยนระดับคะแนนมาคิดรวมด้วย \nโดยผู้สำเร็จการศึกษาที่จะได้รับปริญญาเกียรตินิยมจะต้องอยู่ในเกณฑ์ ต่อไปนี้\n1. สำเร็จการศึกษาไม่เกินระยะเวลาปกติที่กำหนดไว้ในหลักสูตร ทั้งนี้ไม่นับเวลาที่ได้รับอนุมัติให้\nลาพักการศึกษา\n2. ไม่เคยได้รับค่าคะแนน F หรือ R หรือ U ในรายวิชาใด\n3.ไม่เคยได้รับการยกเว้นรายวิชา เว้นแต่เป็นการยกเว้นรายวิชาที่มหาวิทยาลัยกำหนดให้ยกเว้นได้ โดยไม่มีผลต่อการให้ปริญญาเกียรตินิยม\n4.ในกรณีนักศึกษาที่เทียบโอนรายวิชาในหลักสูตรจากสถาบันการศึกษาอื่นจะต้องศึกษา รายวิชาในหลักสูตรของมหาวิทยาลัยไม่น้อยกว่าสามในสี่ของจำนวนหน่วยกิตรวมตลอดหลักสูตร', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (52, 6, 'ถอนรายวิชาติด W ได้รับเกียรตินิยมหรือไม่', 'ถอนรายวิชา, W, เกียรตินิยม', '', 'การถอนรายวิชาติด W ยังได้รับปริญญาเกียรตินิยม โดยมีหลักเกณฑ์ดังนี้\n1. ปริญญาเกียรตินิยมอันดับหนึ่ง ให้กับผู้สำเร็จการศึกษาชั้นปริญญาตรีที่ได้รับคะแนนเฉลี่ย สะสมไม่ต่ำกว่า3.60\n2. ปริญญาเกียรตินิยมอันดับสอง ให้กับผู้สำเร็จการศึกษาชั้นปริญญาตรีที่ได้รับคะแนนเฉลี่ย สะสมไม่ต่ำกว่า3.25 \nแต่ต่ำกว่า 3.60\nการคิดคะแนนเฉลี่ยสะสมเพื่อรับปริญญาเกียรตินิยมตามวรรคหนึ่ง ไม่ให้นำระดับคะแนนส่วนที่เป็นการลงทะเบียนเรียนซ้ำเพื่อเปลี่ยนระดับคะแนนมาคิดรวมด้วย \nโดยผู้สำเร็จการศึกษาที่จะได้รับปริญญาเกียรตินิยมจะต้องอยู่ในเกณฑ์ ต่อไปนี้\n1. สำเร็จการศึกษาไม่เกินระยะเวลาปกติที่กำหนดไว้ในหลักสูตร ทั้งนี้ไม่นับเวลาที่ได้รับอนุมัติให้\nลาพักการศึกษา\n2. ไม่เคยได้รับค่าคะแนน F หรือ R หรือ U ในรายวิชาใด\n3.ไม่เคยได้รับการยกเว้นรายวิชา เว้นแต่เป็นการยกเว้นรายวิชาที่มหาวิทยาลัยกำหนดให้ยกเว้นได้ โดยไม่มีผลต่อการให้ปริญญาเกียรตินิยม\n4.ในกรณีนักศึกษาที่เทียบโอนรายวิชาในหลักสูตรจากสถาบันการศึกษาอื่นจะต้องศึกษา รายวิชาในหลักสูตรของมหาวิทยาลัยไม่น้อยกว่าสามในสี่ของจำนวนหน่วยกิตรวมตลอดหลักสูตร\nรายละเอียด : https://drive.google.com/file/d/1XJTbQO6m2ZDFynQ_tAYnLCnCg-NOx8wn/view?usp=drive_link', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (53, 6, 'การลาพักการศึกษา ได้รับเกียรตินิยมหรือไม่', 'ลาพักการศึกษา, เกียรตินิยม', 'การได้รับเกียรตินิยม', 'การลาพักการศึกษา สามารถได้รับปริญญาเกียรตินิยม ทั้งนี้ระยะเวลาการศึกษาปกติต้องไม่เกินที่กำหนดไว้ในหลักสูตร โดยมีหลักเกณฑ์ดังนี้\n1. ปริญญาเกียรตินิยมอันดับหนึ่ง ให้กับผู้สำเร็จการศึกษาชั้นปริญญาตรีที่ได้รับคะแนนเฉลี่ย สะสมไม่ต่ำกว่า3.60\n2. ปริญญาเกียรตินิยมอันดับสอง ให้กับผู้สำเร็จการศึกษาชั้นปริญญาตรีที่ได้รับคะแนนเฉลี่ย สะสมไม่ต่ำกว่า3.25 \nแต่ต่ำกว่า 3.60\nการคิดคะแนนเฉลี่ยสะสมเพื่อรับปริญญาเกียรตินิยมตามวรรคหนึ่ง ไม่ให้นำระดับคะแนนส่วนที่เป็นการลงทะเบียนเรียนซ้ำเพื่อเปลี่ยนระดับคะแนนมาคิดรวมด้วย \nโดยผู้สำเร็จการศึกษาที่จะได้รับปริญญาเกียรตินิยมจะต้องอยู่ในเกณฑ์ ต่อไปนี้\n1. สำเร็จการศึกษาไม่เกินระยะเวลาปกติที่กำหนดไว้ในหลักสูตร ทั้งนี้ไม่นับเวลาที่ได้รับอนุมัติให้\nลาพักการศึกษา\n2. ไม่เคยได้รับค่าคะแนน F หรือ R หรือ U ในรายวิชาใด\n3.ไม่เคยได้รับการยกเว้นรายวิชา เว้นแต่เป็นการยกเว้นรายวิชาที่มหาวิทยาลัยกำหนดให้ยกเว้นได้ โดยไม่มีผลต่อการให้ปริญญาเกียรตินิยม\n4.ในกรณีนักศึกษาที่เทียบโอนรายวิชาในหลักสูตรจากสถาบันการศึกษาอื่นจะต้องศึกษา รายวิชาในหลักสูตรของมหาวิทยาลัยไม่น้อยกว่าสามในสี่ของจำนวนหน่วยกิตรวมตลอดหลักสูตร\nรายละเอียด : https://drive.google.com/file/d/1XJTbQO6m2ZDFynQ_tAYnLCnCg-NOx8wn/view?usp=drive_link', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (54, 6, 'จะขอใบเทียบหน่วยกิตเพื่อนำไปสมัครสอบครูผู้ช่วย 2 วิชาเอก  ดังนี้\n1.เอกวิทยาศาสตร์\n2.เอกวิทยาศาสตร์ทั่วไป\nต้องดำเนินการอย่างไร', 'ใบเทียบหน่วยกิต, สอบครูผู้ช่วย, เอกวิทยาศาสตร์, เอกวิทยาศาสตร์ทั่วไป', 'สมัครงาน,ขอเอกสารเทียบหน่วยกิตเพื่อสมัครงาน,เอกวิทยาศาสตร์,เอกวิทยาศาสตร์ทั่วไป', '1. กรอกข้อมูลเเบบฟอร์มให้เรียบร้อย\r\n2. นำฟอร์มส่งไปยังสาขาวิชา ให้หัวหน้าสาขาหรือประธานหลักสูตรลงนามให้ในหน้าที่ 2\r\n3. ส่งฟอร์มกลับมาที่อีเมล wisawi@kku.ac.th (กรณีออนไลน์) หรือนำมาส่งที่งานบริการการศึกษาฯ (กรณีมาดำเนินการเอง) เพื่องานบริการการศึกษาฯ ดำเนินการเสนอให้คณบดีลงนาม\r\n4. นำฟอร์มไปขอหนังสือรับรองหน่วยกิตกับสำนักบริหารเเละพัฒนาวิชาการ \r\n     4.1 กรณีมาดำเนินการเอง ไปที่ตึกพิมล ห้องกระจกสีส้มชั้น 1\r\n     4.2 กรณีออนไลน์ แอดไลน์ไปที่ ->  https://line.me/R/ti/p/@634zsgdl   เมื่อเอกสารได้รับอนุมัติตามขั้นตอนที่ 1-3 แล้ว ส่งเเบบฟอร์มเข้าไปในไลน์ตามลิงค์ข้างบน แล้วขอเอกสารออนไลน์ที่ระบบ reg.kku.ac.th ให้ขอเป็นหนังสือรับรองสำเร็จการศึกษาฉบับภาษาไทย โดยระบุที่ช่องหมายเหตุว่า ขอหนังสือรับรองหน่วยกิตและได้ส่งแบบฟอร์มเเล้วที่ Line ระบุชื่อ Line ตัวเองลงในช่องหมายเหตุด้วยครับ', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (55, 6, 'เกณฑ์ในการให้เกียรตินิยม', 'เกณฑ์, เกียรตินิยม', 'เกียรตินิยม,เกณฑ์ในการให้เกียรตินิยม', 'ปริญญาเกียรตินิยมแบ่งได้ดังนี้\n1. ปริญญาเกียรตินิยมอันดับหนึ่ง ให้กับผู้สำเร็จการศึกษาชั้นปริญญาตรีที่ได้รับคะแนนเฉลี่ย สะสมไม่ต่ำกว่า3.60\n2. ปริญญาเกียรตินิยมอันดับสอง ให้กับผู้สำเร็จการศึกษาชั้นปริญญาตรีที่ได้รับคะแนนเฉลี่ย สะสมไม่ต่ำกว่า3.25 \nแต่ต่ำกว่า 3.60\nการคิดคะแนนเฉลี่ยสะสมเพื่อรับปริญญาเกียรตินิยมตามวรรคหนึ่ง ไม่ให้นำระดับคะแนนส่วนที่เป็นการลงทะเบียนเรียนซ้ำเพื่อเปลี่ยนระดับคะแนนมาคิดรวมด้วย \nโดยผู้สำเร็จการศึกษาที่จะได้รับปริญญาเกียรตินิยมจะต้องอยู่ในเกณฑ์ ต่อไปนี้\n1. สำเร็จการศึกษาไม่เกินระยะเวลาปกติที่กำหนดไว้ในหลักสูตร ทั้งนี้ไม่นับเวลาที่ได้รับอนุมัติให้\nลาพักการศึกษา\n2. ไม่เคยได้รับค่าคะแนน F หรือ R หรือ U ในรายวิชาใด\n3.ไม่เคยได้รับการยกเว้นรายวิชา เว้นแต่เป็นการยกเว้นรายวิชาที่มหาวิทยาลัยกำหนดให้ยกเว้นได้ โดยไม่มีผลต่อการให้ปริญญาเกียรตินิยม\n4.ในกรณีนักศึกษาที่เทียบโอนรายวิชาในหลักสูตรจากสถาบันการศึกษาอื่นจะต้องศึกษา รายวิชาในหลักสูตรของมหาวิทยาลัยไม่น้อยกว่าสามในสี่ของจำนวนหน่วยกิตรวมตลอดหลักสูตร\nรายละเอียด : https://drive.google.com/file/d/1XJTbQO6m2ZDFynQ_tAYnLCnCg-NOx8wn/view?usp=drive_link', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (56, 7, 'นักศึกษาจะออกปฏิบัติสหกิจศึกษา ต้องมีคุณสมบัติอะไรบ้าง', 'สหกิจศึกษา, คุณสมบัติ', 'สหกิจ', '1.เป็นนักศึกษาชั้นปีที่ 4 หรือได้รับพิจารณาตามความเหมาะสมจากสาขาวิชา \n\n2.ไม่เคยต้องโทษวินัยนักศึกษาขั้นร้ายแรง \n\n3. คุณสมบัติอื่นๆ เป็นไปตามเกณฑ์ของแต่ละสาขาวิชาระบุ เช่น ผลการเรียนวิชาเฉพาะ เป็นต้น \n\n4. ได้รับความเห็นชอบจากผู้ปกครองและอาจารย์ที่ปรึกษาให้สมัครเรียนรายวิชาสหกิจศึกษา \n\n5. ต้องผ่านการอบรม เพื่อเตรียมความพร้อมก่อนปฏิบัติงานสหกิจศึกษาสำหรับนักศึกษาคณะวิทยาศาสตร์ (ไม่น้อยกว่า 30 ชั่วโมง)\n\nรายละเอียด : https://sc.kku.ac.th/cwie/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (57, 7, 'ต้องติดต่อใครเพื่อขอคำแนะนำก่อนเลือกไปสหกิจศึกษา', 'สหกิจศึกษา, คำแนะนำ', 'สหกิจ', 'อาจารย์ที่ดูแลสหกิจศึกษาของแต่ละสาขาวิชา\nรายละเอียด : https://sc.kku.ac.th/cwie/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (58, 7, 'หน่วยงานที่รับนักศึกษาสหกิจศึกษา มีที่ไหนบ้าง', 'สหกิจ', '', '-สหกิจศึกษาในประเทศ : นักศึกษาสามารถ login และเข้าดูข้อมูลได้ที่ website สหกิจศึกษาของคณะวิทยาศาสตร์\n-สหกิจศึกษานานาชาติ : นักศึกษาสามารถ login และเข้าดูข้อมูลได้ที่ website สหกิจศึกษาของมหาวิทยาลัยขอนแก่น', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (59, 7, 'มีทุนสนับสนุนให้นักศึกษาฝึกสหกิจศึกษาหรือไม่', 'ทุนสหกิจ', '', '-สหกิจศึกษาในประเทศ : คณะฯ สนับสนุน 2,000.- บาทต่อคน และสาขาวิชา สนับสนุนตามงบประมาณที่สาขาวิชาตั้งงบประมาณไว้\n-สหกิจศึกษานานาชาติ :แบ่งตามกลุ่มประเทศตามรายละเอียดแนบท้ายประกาศ และกาหนดอัตรา ดังนี้\n1) ประเทศกลุ่มที่ 1 จานวนเงินทุนสมทบร่วมกันแล้วเป็นเงินไม่เกิน 45,000 บาท\n2) ประเทศกลุ่มที่ 2 จานวนเงินทุนสมทบร่วมกันแล้วเป็นเงินไม่เกิน 48,000 บาท\n3) ประเทศกลุ่มที่ 3 จานวนเงินทุนสมทบร่วมกันแล้วเป็นเงินไม่เกิน 50,000 บาท\nโดยใช้หลักการสมทบเงินทุนร่วมระหว่างมหาวิทยาลัยและคณะแบบร่วมจ่าย (Co-payment) ในสัดส่วนร้อยละ 50:50', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (60, 7, 'จะไปสหกิจศึกษาต่างประเทศต้องทำอย่างไร/อยากไปสหกิจต่างประเทศ/ทุนสนับสนุนสหกิจต่างประเทศ', 'สหกิจต่างประเทศ', '', 'เตรียมเอกสาร ดังนี้\n1.หลักฐานการตอบรับนักศึกษาเข้าปฏิบัติสหกิจศึกษาฯ จากสถานประกอบการ\n2.สำเนาบัตรประชาชน (ที่ยังไม่หมดอายุ)\n3.สำเนาบัตรนักศึกษา (ที่ยังไม่หมดอายุ)\n4.สำเนาหนังสือเดินทาง (passport)\n5.ใบยินยอมผู้ปกครอง (ดาวโหลดที่ลิงก์ :  https://drive.google.com/drive/folders/1z2gj0mNK0h-9B-SP9RoDr7c34oNSfF2c)\n6.หลักฐานการซื้อประกันสุขภาพและอุบัติเหตุ\nเพื่อสมัครในระบบ cwie.kku.ac.th', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (61, 7, 'ฝึกงานกับสหกิจศึกษาต่างกันอย่างไร', 'ฝึกงานกับสหกิจ', '', '1. ระยะเวลา\n2.รูปแบบของการขอเข้าไปปฏิบัติสหกิจศึกษาหรือฝึกงาน\n3.สถานะของนักศึกษาในองค์กรผู้ใช้บัณฑิต(สถานประกอบการ)\n4.คุณสมบัติของนักศึกษา\n5.เงินเดือนหรือค่าตอบแทนหรือสวัสดิการอื่น ๆที่ได้รับ\n6.ลักษณะการทำงาน(งานคุณภาพ)\n7.ระยะเวลาการปฏิบัติงาน\n8.การประสานงานกันระหว่างสถาบันอุดมศึกษากับองค์กรผู้ใช้บัณฑิต(สถานประกอบการ)\n9.การดูแลนักศึกษาระหว่างการปฏิบัติงาน\n10.การส่งผลการปฏิบัติงานของนักศึกษา\n11.การติดตามผลการปฏิบัติงาน \n12.การประเมินผล (ผลสัมฤทธิ)\n13.การสรุปผลการปฏิบัติงาน', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (62, 7, 'ไปฝึกงานหรือสหกิจศึกษาต้องมีค่าใช้จ่ายเพิ่มเติมหรือไม่', 'ฝึกงานกับสหกิจ', '', 'หากไปฝึกงานหรือสหกิจศึกษาต่างจังหวัด (สถานประกอบการที่ไม่ใช่จังหวัดขอนแก่น) จะมีค่าใช่จ่ายเพิ่ม อาทิ ค่าที่พัก ค่าเดินทาง ที่นักศึกษาต้องรับผิดชอยค่าใช้จ่ายเอง', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (63, 8, 'การลงทะเบียนเรียนน้อยกว่า/มากกว่า จำนวนที่กำหนด ดำเนินการอย่างไร?', 'ลงทะเบียนเรียน, น้อยกว่า, มากกว่า', 'ลงทะเบียนน้อยกว่า,บัณฑิตศึกษา', 'การลงทะเบียนเรียนในภาคการศึกษาปกติ ลงได้ 1-15 หน่วยกิต ผ่าน reg ได้เลย\n\nสำหรับการลงทะเบียนวิชาเรียนน้อยกว่ากรณีขอชำระ (1-3) หรือมากกว่าที่กำหนด (16-22)  จะกระทำได้ในกรณีต่อไปนี้\n1.1 จำนวนหน่วยกิตที่เหลือตามหลักสูตร มีจำนวนน้อยกวาหรือมากกว่าที่กำหนดและจำเป็นต้องสำเร็จการศึกษาในภาคการศึกษานั้น ๆ\n1.2 แผนการเรียนในหลักสูตรกำหนดจำนวนหน่วยกิตที่น้อยกวาหรือมากกว่าที่กำหนด\n1.3 ได้รับการเทียบโอนรายวิชาแล้ว เหลือจำนวนหน่วยกิตน้อยกว่าหรือมากกว่าที่กำหนด\n1.4 ได้รับอนุมัติให้ปรับเปลี่ยนแผนการเรียน\n1.5 กรณีอื่นๆ ตามที่คณะกรรมการประจำบัณฑิตวิทยาลัยเห็นชอบ\nทั้งนี้ต้องได้รับอนุมัติจากคณบดีที่เกี่ยวข้อง ตามความเห็นชอบของคณะกรรมการบริหารหลักสูตร\n\nขั้นตอนของการดำเนินการ:\nนักศึกษายื่นคำร้องขอลงทะเบียนน้อยกว่า/มากกว่าที่กำหนด (บว.9) ผ่าน gs form\nนักศึกษาตรวจสอบในระบบทะเบียนเรียน (reg.kku.ac.th) เมื่อดำเนินการเรียบร้อย\nรายละเอียด : https://app.gs.kku.ac.th/gs/th/page/announcements_gs/register', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (64, 8, 'ไม่สามารถลงทะเบียนเรียนรายวิชาวิทยานิพนธ์ได้', 'ลงทะเบียนเรียน, รายวิชาวิทยานิพนธ์', 'ลงทะเบียนไม่ได้,ลงทะเบียนเรียน ระดับบัณฑิตศึกษา', '1.กรณีลงทะเบียนครั้งแรก สำหรับการลงทะเบียนเรียนวิทยานิพนธ์ครั้งแรก นักศึกษาจำเป็นต้องเสนอแต่งตั้งอาจารย์ที่ปรึกษาวิทยานิพนธ์ (บว.21) ผ่าน https://forms.gs.kku.ac.th (ซึ่งจำเป็นต้องแนบไฟล์หลักฐานประวัติและผลงานของอาจารย์ เพื่อตรวจสอบคุณสมบัติของอาจารย์ที่จะแต่งตั้ง) ก่อนการลงทะเบียนเรียน หากนักศึกษาทราบชื่ออาจารย์ที่ปรึกษาวิทยานิพนธ์ก่อนการลงทะเบียนเรียนสามารถยื่นคำร้องได้ก่อนเลยไม่ต้องยื่นในช่วงของการลงทะเบียน\n2.กรณีลงทะเบียนครั้งที่สองเป็นต้นไป อาจจะเกิดจากการสำรองที่นั่งไม่ตรงกับรหัสหลักสูตรของนักศึกษา ขอให้ติดต่อ กลุ่มภาระงานด้านบัณฑิตศึกษา โทร 0846001149 หรือ 0914210065\nรายละเอียด : https://app.gs.kku.ac.th/gs/regulation_notice/show/1/2566/104', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (65, 8, 'นักศึกษาระดับปริญญาเอกจะขอลงทะเบียนเรียนรายวิชาระดับปริญญาตรี หรือระดับปริญญาโท ได้อย่างไร', 'ลงทะเบียนเรียน, ระดับปริญญาตรี, ระดับปริญญาโท', 'ลงทะเบียนไม่ได้,ลงทะเบียนเรียน ระดับบัณฑิตศึกษา', 'นักศึกษาจะต้องยื่นคำร้องขอลงทะเบียนเรียนต่ำกว่าหลักสูตร ผ่าน req \nรายละเอียด : https://req.kku.ac.th/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (66, 8, 'ลงทะเบียนเรียนผิดประเภทจะดำเนินการแก้ไขอย่างไร', 'ลงทะเบียนเรียน, ผิดประเภท, แก้ไข', 'ลงทะเบียนไม่ได้,ลงทะเบียนเรียน ระดับบัณฑิตศึกษา', '1. กรณีอยู่ในช่วงลงทะเบียนเรียนตามปฏิทินการศึกษา นักศึกษาที่ชำระเงินค่าธรรมเนียมการศึกษาเรียบร้อยแล้ว สามารถถอนรายวิชาที่ลงผิดออกและดำเนินการลงทะเบียนเรียนใหม่ให้ถูกต้องด้วยตนเองได้เลย\n2. กรณีไม่อยู่ในช่วงลงทะเบียนเรียน นักศึกษายื่นคำร้องทั่วไป ระดับบัณฑิตศึกษา (เป็นกระดาษหรือไฟล์ที่ลงนามดิจิทัล) ขอเปลี่ยนประเภทการลงทะเบียนเรียน สามารถดาวโหลดแบบฟอร์มได้จาก https://kku.world/requestsci (มีไฟล์ตัวอย่างให้ดูด้วย) หลังจากอาจารย์ประจำวิชา อาจารย์ที่ปรึกษา ประธานหลักสูตรลงนามแล้ว ให้ส่งคำร้องมาที่กลุ่มภาระงานด้านบัณฑิตศึกษา เพื่อเสนอคณบดีและส่งให้สำนักบริหารและพัฒนาวิชาการพิจารณาต่อไป ซึ่งนักศึกษาจะต้องติดต่อสำนักฯ เพื่อชำระค่าธรรมเนียมการดำเนินการจำนวน 30 บาท และให้ตรวจสอบในระบบทะเบียนเรียน (reg.kku.ac.th) เมื่อดำเนินการเรียบร้อย\nรายละเอียด : https://kku.world/requestsci', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (67, 8, 'ลงทะเบียนเรียนรายวิชาวิทยานิพนธ์ไม่ตรงตามแผนการศึกษา/เกินจำนวนหน่วยกิตที่หลักสูตรกำหนด จะดำเนินการแก้ไขอย่างไร', 'ลงทะเบียนเรียน, รายวิชาวิทยานิพนธ์, แผนการศึกษา, หน่วยกิต', 'ลงทะเบียนไม่ได้,ลงทะเบียนเรียน ระดับบัณฑิตศึกษา', '1. กรณีอยู่ในช่วงลงทะเบียนเรียนตามปฏิทินการศึกษา นักศึกษาที่ชำระเงินค่าธรรมเนียมการศึกษาเรียบร้อยแล้ว สามารถถอนรายวิชาที่ลงผิดออกและดำเนินการลงทะเบียนเรียนใหม่ให้ถูกต้องด้วยตนเองได้เลย\n2. กรณีไม่อยู่ในช่วงลงทะเบียนเรียน นักศึกษายื่นคำร้องทั่วไป ระดับบัณฑิตศึกษา (เป็นกระดาษหรือไฟล์ที่ลงนามดิจิทัล) ขอเปลี่ยนจำนวนหน่วยกิตในการลงทะเบียนเรียน สามารถดาวโหลดแบบฟอร์มได้จาก https://kku.world/requestsci หลังจากอาจารย์ประจำวิชา อาจารย์ที่ปรึกษา ประธานหลักสูตรลงนามแล้ว ให้ส่งคำร้องมาที่กลุ่มภาระงานด้านบัณฑิตศึกษา เพื่อเสนอคณบดีและส่งให้สำนักบริหารและพัฒนาวิชาการพิจารณาต่อไป ซึ่งนักศึกษาจะต้องติดต่อสำนักฯ เพื่อชำระค่าธรรมเนียมการดำเนินการจำนวน 30 บาท และให้ตรวจสอบในระบบทะเบียนเรียน (reg.kku.ac.th) เมื่อดำเนินการเรียบร้อย\nรายละเอียด : https://kku.world/requestsci', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (68, 8, 'กำหนดสอบวิทยานิพนธ์/การศึกษาอิสระ วันสุดท้ายของภาคการศึกษาปัจจุบัน คือวันที่เท่าไร?', 'สอบวิทยานิพนธ์, การศึกษาอิสระ, วันสุดท้าย', 'วิทยานิพนธ์', 'ตามระเบียบมหาวิทยาลัยฯ กำหนดวันสอบวันสุดท้ายของภาคการศึกษาปัจจุบัน ไว้เฉพาะนักศึกษาที่ศึกษาครบตามระยะเวลาการศึกษา\n\n          ส่วนนักศึกษาที่ยังไม่ครบระยะเวลาการศึกษาไม่ได้กำหนดวันสุดท้ายของการสอบไว้ ตามปฏิทินการศึกษากำหนดเฉพาะวันสุดท้ายของการส่งเล่มวิทยานิพนธ์/การศึกษาอิสระ โดยที่ไม่รักษาสถานภาพ ให้นักศึกษานับวันที่จะดำเนินการสอบเอง โดยคำนึงถึงการส่งเล่มให้ทันวันที่กำหนด ส่วนนักศึกษาที่ประสงค์จะรักษาสถานสภาพจะต้องได้รับผลการเรียนครบทุกรายวิชาก่อน จึงจะดำเนินการรักษาสถานสภาพได้ (ให้ดำเนินการตามระยะเวลาที่ปฏิทินการศึกษากำหนดเท่านั้น)\nรายละเอียด : https://registrar.kku.ac.th/kkustudentpage1/academiccalendar', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (69, 8, 'สามารถยื่นขอสอบวิทยานิพนธ์ได้เมื่อไร', 'ยื่นขอสอบ, วิทยานิพนธ์', 'วิทยานิพนธ์', 'นักศึกษายื่น บว.25 ก่อนการสอบไม่น้อยกว่า 20 วัน ผ่าน GS form\nโดยที่อาจารย์ต้องให้ผลการเรียนรายวิชาวิทยานิพนธ์ครบตามหลักสูตรแล้วและผ่านภาษาอังกฤษและบัณฑิตวิทยาลัยออกประกาศรายชื่อผู้ผ่านเรียบร้อยแล้ว\nรายละเอียด : https://www.facebook.com/share/p/1A1N6bVWhn/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (70, 8, 'สามารถยื่นแต่งตั้งกรรมการสอบวิทยานิพนธ์ได้เมื่อไร', 'แต่งตั้งกรรมการสอบ, วิทยานิพนธ์', 'วิทยานิพนธ์', 'อาจารย์ยื่นก่อนการสอบไม่น้อยกว่า 20 วัน ผ่าน GS form โดยที่ บว.25 ในระบบจะต้องได้รับอนุมัติแล้วจึงจะสามารถยื่นได้\nซึ่งการยื่น บว.26 จะเป็นข้อมูลสำหรับ บว.27 และ บว.28 ที่จะต้องให้คณะกรรมการสอบลงนามหลังการสอบ หากดำเนินการช้าจะทำให้บว.27 บว.28 ช้าไปด้วย', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (71, 8, 'การสอบเค้าโครงวิทยานิพนธ์ต้องดำเนินการอย่างไร', 'สอบเค้าโครง, วิทยานิพนธ์', 'เค้าโครงวิทยานิพนธ์', 'การขออนุมัติเค้าโครงกรณีมีการสอบ\nก่อนสอบ\n--นักศึกษาระดับปริญญาเอกจะต้องสอบผ่านการสอบวัดคุณสมบัติแล้ว\n--ยื่นคำร้องขอแต่งตั้งกรรมการสอบเค้าโครง (วท.บศ.05) ก่อนวันสอบ 20 วัน (สำหรับสาขาวิชาที่กำหนดให้มีการสอบ) https://kku.world/05\nยื่นแบบฟอร์ม หลังจากประธานหลักสูตรลงนามแบบ Digital ID ที่ https://kku.world/ac17p (หากลงนามแบบเดิมให้ส่งที่งานบริการฯ) *เข้าสู่ระบบ kkumail กันก่อนยื่นแบบฟอร์มในลิ้งค์นะคะ\nหลังการสอบ (ภายใน 30 วัน)\nให้ดำเนินการกรอกข้อมูล บว.23 ในระบบ GS-e-form ( https://forms.gs.kku.ac.th/ ) โดยอัปโหลดเอกสารเข้าระบบจำนวน 2 ไฟล์ ดังนี้\n1. Turnitin Originality Report form (ไฟล์นี้จะมีทั้งหมด 3 แผ่น ประกอบด้วย แบบฟอร์มที่ อ.ที่ปรึกษาลงนาม + หน้าที่มีชื่อนักศึกษา (ที่ระบุว่า by.....) + หน้าแรกที่แสดง%รวม)\nแบบฟอร์ม https://gsbooks.gs.kku.ac.th/65/manual/files/forms/turnitin-new.pdf\nขั้นตอนการกรอกข้อมูลในระบบ turnitin KKU: https://kku.world/draftcoach\n2. เค้าโครงตามรูปแบบที่คณะกำหนด\nรูปแบบของคณะ https://kku.world/scproposalform\nรายละเอียด : https://www.facebook.com/share/p/17qxYcdFkQ/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (72, 8, 'การสอบวัดคุณสมบัติต้องดำเนินการอย่างไร', 'สอบวัดคุณสมบัติ', 'สอบวัดคุณสมบัติ', 'นักศึกษายื่น บว.30 ก่อนการสอบไม่น้อยกว่า 20 วัน ผ่าน GS form นักศึกษาระดับปริญญาเอกจะต้องสอบผ่านการสอบวัดคุณสมบัติก่อนจึงจะสามารถเสนออนุมัติเค้าโครงได้', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (73, 8, 'การเสนอแต่งตั้งกรรมการสอบวัดคุณสมบัติต้องดำเนินการอย่างไร', 'แต่งตั้งกรรมการสอบ, วัดคุณสมบัติ', 'สอบวัดคุณสมบัติ', 'อาจารย์ยื่น บว.31 ก่อนการสอบไม่น้อยกว่า 20 วัน การจัดสอบวัดคุณสมบัติสามารถดำเนินการได้ภาคการศึกษาละ 1 ครั้ง', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (74, 8, 'ขอทราบช่องทางการติดต่อสอบถามข้อมูลเพิ่มเติม', 'ช่องทางการติดต่อ, ข้อมูลเพิ่มเติม', 'ติดต่อ', '1. เบอร์โทร. 084-6001149, 091-4210065 (ในวันเวลาราชการ)\n2. Facebook กลุ่ม : บัณฑิตศึกษา คณะวิทยาศาสตร์ มข.\nfanpage: Graduate School, Faculty of Science,\nKhon Kaen University\n3. เว็บไซต์กล่มุ ภาระงานด้านบัณฑิตศึกษา: https://sc.kku.ac.th/sci-graduate/\n4. Line group GS SC : งานบัณฑิต คณะวิทยาศาสตร์ มข http://line.me/ti/g/iGTuj5n1eV', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (75, 8, 'เกณฑ์สำเร็จการศึกษา ระดับปริญญาโท แผน 1 แบบ ก 1 มีอะไรบ้าง', 'เกณฑ์สำเร็จการศึกษา, ปริญญาโท, แผน 1, แบบ ก 1', 'การสำเร็จการศึกษา ระดับบัณฑิตศึกษา', '1. สอบวิทยานิพนธ์ผ่าน\n2. ผลงานวิทยานิพนธ์หรือส่วนหนึ่งของวิทยานิพนธ์ได้รับการตีพิมพ์', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (76, 8, 'เกณฑ์สำเร็จการศึกษา ระดับปริญญาโท  แผน 1 แบบ ก 2 มีอะไรบ้าง', 'เกณฑ์สำเร็จการศึกษา, ปริญญาโท, แผน 1, แบบ ก 2', 'การสำเร็จการศึกษา ระดับบัณฑิตศึกษา', '1. มีผลการเรียนเฉลี่ยไม่ต่ำกว่า 3.00\n2. สอบวิทยานิพนธ์ผ่าน\n3. ผลงานวิทยานิพนธ์หรือส่วนหนึ่งของวิทยานิพนธ์ได้รับการเผยแพร่', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (77, 8, 'เกณฑ์สำเร็จการศึกษา ระดับปริญญาเอก มีอะไรบ้าง', 'เกณฑ์สำเร็จการศึกษา, ปริญญาเอก', 'การสำเร็จการศึกษา ระดับบัณฑิตศึกษา', '1. สอบวิทยานิพนธ์ผ่าน\n2. ผลงานวิทยานิพนธ์หรือส่วนหนึ่งของวิทยานิพนธ์ได้รับการตีพิมพ์', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (78, 8, 'การเผยแพร่ผลงานวิทยานิพนธ์ เพื่อสำเร็จการศึกษามีอะไรบ้าง', 'เผยแพร่ผลงาน, วิทยานิพนธ์, สำเร็จการศึกษา', 'การสำเร็จการศึกษา ระดับบัณฑิตศึกษา', 'นักศึกษาสามารถตรวจสอบข้อมูลตามรหัสที่เข้าศึกษา https://drive.google.com/file/d/1Op_MTAy7-JoZgnqPLHHYZz_l4ocnyiHB/view?usp=sharing', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (79, 8, 'หลังจากดำเนินการส่งเล่มวิทยานิพนธ์และเอกสารเผยแพร่ผลงานแล้วจะต้องดำเนินการอย่างไรเพื่อขอสำเร็จการศึกษา', 'ส่งเล่มวิทยานิพนธ์, เอกสารเผยแพร่ผลงาน, ขอสำเร็จการศึกษา', 'การสำเร็จการศึกษา ระดับบัณฑิตศึกษา', 'ให้ดำเนินการส่งเอกสารเพื่อเป็นหลักฐานประกอบการสำเร็จการศึกษา\nไฟล์ที่ต้องส่งคณะ หลังจากผู้เกี่ยวข้องลงนามครบถ้วนแล้ว จำนวน 9 ไฟล์ ตามรายการด้านล่าง ส่งมาที่อีเมลล์ mparach@kku.ac.th\n1. บว37 (https://gsmis.gs.kku.ac.th/)\n2. ปกวารสาร\n3. สารบัญวารสาร\n4. ใบตอบรับ\n5. บทความฉบับเต็ม  \n6. วท.บศ.37  -->  https://kku.world/e72epa\n7. วท.บศ.06  -->  https://kku.world/u3zm2o\n8. ตรวจสอบหนี้สินออนไลน์ (แทนบว20) --> https://reg2.kku.ac.th/kku_sdm\n9. แบบสอบถามเกี่ยวกับหลักสูตร -->  https://kku.world/f1gbq\n\nไฟล์ที่ต้องส่งไปยังบัณฑิตวิทยาลัย อีเมลล์ graduate@kku.ac.th จำนวน 5 ไฟล์\n1. บว37\n2. ปกวารสาร\n3. สารบัญวารสาร\n4. ใบตอบรับ\n5. บทความ', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (80, 8, 'ระยะเวลาที่ใช้ในการดำเนินการสำเร็จการศึกษาหลังจากที่ยื่นเอกสารเรียบร้อยแล้วใช้เวลานานเท่าใด', 'ระยะเวลา, ดำเนินการสำเร็จการศึกษา', 'การสำเร็จการศึกษา ระดับบัณฑิตศึกษา', 'ขั้นตอนการเสนอขออนุมัติสำเร็จการศึกษาจะใช้เวลาประมาณ 1- 2 เดือน หลังจากที่นักศึกษายื่นเอกสารครบถ้วน ซึ่งมีขั้นตอนการดำเนินการ ดังนี้\n1. บัณฑิตวิทยาลัยแจ้งราบชื่อนักศึกษาที่ส่งเอกสารครบถ้วนให้คณะดำเนินการตามขั้นตอนสำเร็จการศึกษาได้\n2. คณะดำเนินการตรวจสอบรายชื่อและข้อมูลที่เกี่ยวข้องกับสำนักบริหารและพัฒนาวิชาการ\n3. เสนอคณะกรรมการประจำคณะวิทยาศาสตร์ (ประชุมเดือนละ 1 ครั้ง ทุกวันพฤหัสบดีสัปดาห์ที่ 3)\n4. เสนอสภามหาวิทยาลัยเพื่อขออนุมัติปริญญา (ประชุมเดือนละ 1 ครั้ง ทุกวันพุธสัปดาห์ที่ 1 และมีรอบเวียนเดือนละ 2 ครั้ง)\n5. สภาแจ้งมติไปยังสำนักบริหารและพัฒนาวิชาการเพื่อเปลี่ยนสถานะเป็นผู้สำเร็จการศึกษา\n6. สามารถขอเอกสารหลักฐานการสำเร็จการศึกษาได้หลังจากการประชุมผ่านไปประมาณ 1 - 2 สัปดาห์', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (81, 8, 'จะยื่นขอยกเว้น / ลดหย่อน ค่าธรรมเนียมวิจัยอย่างไร', 'ยกเว้น, ลดหย่อน, ค่าธรรมเนียมวิจัย', 'ค่าธรรมเนียมการวิจัย', 'การยื่นแบบการขอลดหย่อนค่าธรรมเนียมการวิจัยตามหลักสูตรระดับบัณฑิตศึกษา (วท.บศ.04) \nต้องดำเนินการทุกภาคการศึกษาที่ลงทะเบียนเรียน\n-อาจารย์ลงนามแบบดิจิทัล สามารถส่งไฟล์ที่ E-mail: mparach@kku.ac.th ระบุชื่อเรื่อง ขอส่งแบบการขอลดหย่อนค่าธรรมเนียมการวิจัย\n-อาจารย์ลงนามจริง ให้ส่งตัวจริงนะคะ\nDownload แบบฟอร์ม \nภาษาไทย https://kku.world/scgs04thai\nภาษาอังกฤษ https://kku.world/scgs04eng', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (82, 8, 'จะขอตรวจสอบว่ายื่นคำร้องค่าธรรมเนียมวิจัยแล้วหรือยังจะต้องดำเนินการอย่างไร', 'ตรวจสอบ, คำร้อง, ค่าธรรมเนียมวิจัย', 'ค่าธรรมเนียมการวิจัย', 'ติดต่อคุณปารัชญ์ โคธิเสน (พี่เป๋า) เพื่อตรวจสอบในระบบให้ผ่านช่องทาง\n1. เบอร์โทร. 084-6001149, 091-4210065 (ในวันเวลาราชการ)\n2. Facebook กลุ่ม : บัณฑิตศึกษา คณะวิทยาศาสตร์ มข.\nfanpage: Graduate School, Faculty of Science,\nKhon Kaen University\n3. เว็บไซต์กล่มุ ภาระงานด้านบัณฑิตศึกษา: https://sc.kku.ac.th/sci-graduate/\n4. Line group GS SC : งานบัณฑิต คณะวิทยาศาสตร์ มข http://line.me/ti/g/iGTuj5n1eV\"', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (83, 8, 'ช่วงเวลารับสมัครเข้าศึกษาระดับบัณฑิตศึกษา', 'รับสมัคร, ระดับบัณฑิตศึกษา', 'รับเข้าโท เอก', 'การรับสมัครเข้าศึกษาระดับบัณฑิตศึกษา สามารถสมัครผ่านระบบออนไลน์\nภาคต้น ช่วงที่ 1 เปิดรับสมัคร 1 ธันวาคม ปีนี้ - 31 มกราคม ปีถัดไป\nภาคต้น ช่วงที่ 2 เปิดรับสมัคร 1 มีนาคม - 30 เมษายน\nภาคปลาย เปิดรับสมัคร 1 กรกฎาคม - 31 สิงหาคม\nรายละเอียด : https://admission.gs.kku.ac.th/dashboard', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (84, 8, 'การรับเข้าศึกษาระดับบัณฑิตศึกษากรณีรับเข้าตลอดปี', 'รับเข้าศึกษา, ระดับบัณฑิตศึกษา, ตลอดปี', 'รับเข้าโท เอก', 'การรับเข้าศึกษาตลอดปี ผู้สมัครสามารถดำเนินการ 4 ช่องทาง \r\n1) ช่องทางหลักที่ 1 สมัครผ่านเว็บไซต์บัณฑิตวิทยาลัย ผู้สนใจสมัครสามารถกรอกข้อมูลการสมัครผ่านเว็บไซต์บัณฑิตวิทยาลัย โดยบัณฑิตวิทยาลัย จะเป็นผู้ดำเนินการส่งข้อมูลผู้สมัครดังกล่าวให้กับหลักสูตรนั้นๆ หลักสูตรพิจารณาการรับเข้า โดยผ่านความเห็นชอบของคณะบริการบริหารหลักสูตร กรรมการประจำคณะ และแจ้งผลการพิจารณาให้บัณฑิตวิทยาลัย เพื่อประสานงานการรับเข้าต่อไป\r\n2)   ช่องทางหลักที่ 2 ยื่นสมัครที่หลักสูตรนั้น ๆ หลักสูตรพิจารณาการรับเข้า\r\n      โดยผ่านความเห็นชอบของคณะกรรมการบริหารหลักสูตร คณะกรรมการประจำคณะ และแจ้งผลการ พิจารณาให้ บัณฑิตวิทยาลัยเพื่อพิจารณาอนุมัติ และประสานงานการรับเข้าต่อไป\r\n3)    ช่องทางรอง ยื่นสมัครผ่านบัณฑิตวิทยาลัย ผ่านช่องทางอื่น ๆ\r\n       นอกเหนือจากเว็บไซต์บัณฑิตวิทยาลัย บัณฑิตวิทยาลัยส่งข้อมูลผู้สมัครให้หลักสูตรนั้น ๆ เป็นผู้พิจารณา รับเข้า โดยผ่านความเห็นชอบของคณะกรรมการบริหารหลักสูตร คณะกรรมการประจำคณะ และแจ้งผลการพิจารณาให้บัณฑิตวิทยาลัยเพื่อพิจารณาอนุมัติ และประสานงานการรับเข้าต่อไป\r\n4) ยื่นสมัครผ่านช่องทางอื่น ๆ ที่บัณฑิตวิทยาลัยกำหนด ทั้งนี้ ผู้สมัครต้องมีหนังสือตอบรับของอาจารย์ที่ปรึกษาวิทยานิพนธ์หรือ การศึกษาอิสระ ที่เป็นอาจารย์ประจำหลักสูตรที่ผู้สมัครประสงค์จะเข้าศึกษา โดยผ่านความเห็นชอบของคณะกรรมการบริหารหลักสูตร', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (85, 8, 'จะเปลี่ยนแปลงอาจารย์ที่ปรึกษาวิทยานิพนธ์/เพิ่มอาจารย์ที่ปรึกษาร่วม จะต้องทำอย่างไร', 'เปลี่ยนแปลงอาจารย์ที่ปรึกษา, วิทยานิพนธ์, เพิ่มอาจารย์ที่ปรึกษาร่วม', 'อาจารย์ที่ปรึกษาวิทยานิพนธ์', 'นักศึกษาสามารถยื่น บว.21 ผ่าน https://forms.gs.kku.ac.th โดยคลิกเลือกตามกรณีที่ต้องการใน GS Form ซึ่งจำเป็นต้องแนบไฟล์หลักฐานประวัติและผลงานของอาจารย์ เพื่อตรวจสอบคุณสมบัติของอาจารย์ที่จะแต่งตั้ง', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (86, 9, 'ทุนอุดหนุนการศึกษาคณะวิทยาศาสตร์มีอะไรบ้าง,ทุนมหาวิทยาลัยขอนแก่น กับทุนคณะวิทยาศาสตร์ มีข้อแตกต่างกันอย่างไร', 'ทุนอุดหนุนการศึกษา, คณะวิทยาศาสตร์,ทุนการศึกษา', 'ทุนมหาวิทยาลัยขอนแก่น,ทุนคณะวิทยาศาสตร์,ข้อแตกต่างทุน', 'ทุุนแบ่งเป็น 2 ประเภท คือ\r\nทุนประเภท ก จัดสรรโดยมหาวิทยาลัยขอนแก่น\r\n1) ทุนประเภท ก ผู้มีสิทธิ์สมัครจะต้องเป็นนักศึกษาชั้นปีที่ 1 บิดามารดาหรือผู้ปกครองมีรายได้ไม่เกินปีละ 150,000 บาท \r\n2) บิดามารดาหรือผู้ปกครองมีรายได้ไม่เกินปีละ 300,000 แต่มีบุตรหรือผู้อยู่ในอุปการะกำลังศึกษาในระดับมัธยมศึกษาตอนปลายหรือเทียบเท่าขึ้นมากกว่า 1 คน หรือ\r\n3) นักศึกษาไม่มีบิดา  มารดา หรือผู้อุปการะอย่างแท้จริง โดยมีหลักฐานยืนยันว่าสมควรได้รับการสนับสนุนภายใต้ประกาศนี้\r\n4) ไม่เป็นผู้ได้รับทุนอื่นใด ยกเว้นเป็นผู้ที่ได้รับความเห็นชอบจากคณะอนุกรรมการทุนการศึกษา\r\n5) เป็นผู้มีความประพฤติดี เป็นสุภาพชน\r\n6) จะได้รับทุนมูลค่า 30,000 บาท/ปี กรณีขึ้นปี 2 เกรดควรไม่ต่ำกว่า 2.50 \r\nทุนประเภท ข. \r\n           เป็นทุนที่บริษัท ห้างร้าน มูลนิธิ องค์กร หน่วยงาน หรือบุคคลบริจาคให้กับมหาวิทยาลัย หรือคณะเพื่อเป็นทุนการศึกษา ให้กับนักศึกษา เช่น\r\n  - ทุนพระราชทานสยามบรมราชกุมารีในวาระครบรอบ 40 ปี มข. จัดสรรโดยมหาวิทยาลัย\r\n  - ทุนที่ได้รับจากมูลนิธิ บริษัท ห้างร้าน องค์กร หน่วยงงานต่าง ๆ เช่น ทุนวิจิตรพงพษ์พันธ์ ทุนมูลนิธิจุมภฎ-พันธ์ทิพย์ ทุนชวน รัตนรัตน์ ทุนหอการค้าญี่ปุ่น ทุนหอการค้าอเมริกัน เป็นต้น\r\n  - ทุนอุดหนุนคณะวิทยาศาสตร์ ผ่านกองทุน 50 ปี คณะวิทยาศาสตร์\r\n  - ทุนอุดหนุนการศึกษาจากสาขาวิชา คณะวิทยาศาสตร์', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (87, 9, 'ทุนอุดหนุนการศึกษาคณะวิทยาศาสตร์รับสมัครช่วงไหน และขั้นตอนการสมัครอย่างไรบ้าง', 'ทุนอุดหนุนการศึกษา, คณะวิทยาศาสตร์, รับสมัคร, ขั้นตอนการสมัคร', 'รับสมัครทุน,ขั้นตอนการสมัครทุน', 'ภาคต้นปีการศึกษาจะเปิดรับทุน ดังนี้\r\n1) ทุนประเภท ก. และ ข จะเปิดรับสมัครก่อนเปิดเทอมใช้ระยะเวลารับสมัครประมาณ 30-40 วัน โดยต้องสมัครที่ระบบสมัครทุนของมหาวิทยาลัยเท่านั้น และให้สัมภาษณ์ที่คณะที่นักศึกษาสังกัดก่อน  เมื่อคณะสัมภาษณ์เสร็จจะคัดเลือกผู้ที่ขาดแคลนทุนทรัพย์ที่เข้าเกณฑ์ทุนประเภท ก. และ ข ของส่วนกลางส่งตามโควต้าที่ส่วนกลางกำหนด (หากคณะใดมีผู้สมัครทุนมากก็จะได้โควต้ามาก) \r\n2) กรรมการพิจารณาทุนส่วนกลางจะสัมภาษณ์นักศึกษาที่ส่งมาจากคณะ เพื่อรับทุนประเภท ก และ ข และทุนพระราชทานสยามบรมราชกุมารี ในวาระครบรอบ 40 ปี มข.\r\n3) ส่วนกลางประกาศรายชื่อผู้รับทุนส่วนกลาง \r\n4) คณะกรรมการพิจารณาทุนอุดหนุนคณะพิจารณรายชื่อนักศึกษาเพื่อรับทุนอุดหนุนการศึกษาคณะ\r\n5) ประกาศรายชื่อผู้รับทุนคณะ\r\n\r\nภาคปลาย \r\n1) ทุนประเภท ข จะเปิดรับสมัครก่อนเปิดเทอมใช้ระยะเวลารับสมัครประมาณ 30 วัน โดยต้องสมัครที่ระบบสมัครทุนของมหาวิทยาลัยเท่านั้น และให้สัมภาษณ์ที่คณะที่นักศึกษาสังกัดก่อน  เมื่อคณะสัมภาษณ์เสร็จจะคัดเลือกผู้ที่ขาดแคลนทุนทรัพย์ที่เข้าเกณฑ์ทุนประเภท ข ของส่วนกลางส่งตามจำนวนโควต้าที่ส่วนกลางกำหนด (เอาจำนวนทุนส่วนกลางคำนวณเฉลี่ยจากจำนวนผู้สมัครแต่ละคณะ หากคณะใดมีผู้สมัครทุนมากก็จะได้โควต้าส่งไปสัมภาษณ์ทุนส่วนกลางมาก) \r\n2) กรรมการพิจารณาทุนส่วนกลางจะสัมภาษณ์นักศึกษาที่ส่งมาจากคณะ เพื่อรับทุนประเภท ก และ ข และทุนพระราชทานสยามบรมราชกุมารี ในวาระครบรอบ 40 ปี มข.\r\n3) ส่วนกลางประกาศรายชื่อผู้รับทุนส่วนกลาง \r\n4) คณะกรรมการพิจารณาทุนอุดหนุนคณะพิจารณรายชื่อนักศึกษาเพื่อรับทุนอุดหนุนการศึกษาคณะ\r\n5) ประกาศรายชื่อผู้รับทุนคณะ', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (88, 10, 'การรักษาพยาบาลของนักศึกษามหาวิทยาลัยขอนแก่น', 'สวัสดิการนักศึกษา, รักษาพยาบาล, มหาวิทยาลัยขอนแก่น', 'สิทธิการรักษาพยาบาล', 'สิทธิการรักษาพยาบาลมี 3 สิทธิหลัก คือ\r\n1. สิทธิประกันสุขภาพ (บัตรทอง) นักศึกษาต้องแจ้งย้ายสิทธิ์มาเป็นบัตรทองโรงพยาบาลศรีนครินทร์ก่อน ซึ่งนักศึกษาจะไม่ต้องจ่ายค่ารักษายกเว้นยานอกบัญชี หรือเวชภัณฑ์ที่เกินสิทธิ์บัตรทอง\r\n2. สิทธิประกันสังคมโรงพยาบาลศรีนครินทร์ เมื่อเข้ารับการบริการที่ศูนย์สุขภาพตามข้อ 1. นักศึกษาไม่ต้องจ่ายค่ารักษาพยาบาล\r\n3. สิทธิเบิกได้ (บุตรข้าราชการจะเบิกได้ไม่เกินอายุ 20 ปี)  กรณีอายุครบ 20 ปี บริบูรณ์นักศึกษาต้องทำเรื่องกรอกข้อมูลตามแบบฟอร์มขอใช้สิทธิ์บัตรทองที่โรงพยาบาลศรีนครินทร์ได้ที่ศูนย์สุขภาพที่เป็นเครือข่ายของโรงพยาบาลศรีนครินทร์ตามวัน เวลาที่เปิดให้บริการ)\nลิงค์ : https://www.facebook.com/profile.php?id=61563625470249&locale=th_TH', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (89, 10, 'สถานที่ให้บริการรักษานักศึกษามีที่่ไหนบ้างนอกจาก รพ.ศรีครินทร์', 'สถานที่ให้บริการรักษา, นักศึกษา, รพ.ศรีนครินทร์', 'สถานที่ให้บริการตรวจรักษานักศึกษา', '1. ศูนย์สุขภาพนักศึกษา ตั้งอยู่ศูนย์อาหาร (Complex) เปิดวันราชการเวลา 08.00-20.00 น. (มีแพทย์ตรวจ)\n2. ศูนย์สุขภาพ 123 มข. ตั้งอยู่หอพัก 8 หลัง เปิดวันราชการเวลา 08.00-20.00 น. (มีแพทย์ตรวจ)\n3. ศูนย์สุขภาพสามเหลี่ยม ตั้งอยู่ชุมชนสามเหลี่ยม 1 หลัง โรงพยาบาลกรุงเทพ-ขอนแก่น เปิดทุกวัน \nลิงค์ : https://www.facebook.com/profile.php?id=61563625470249&locale=th_TH', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (90, 10, 'นักศึกษาอยากทราบว่าตัวเองมีสิทธิการรักษาอะไรบ้าง ต้องตรวจสอบได้ที่ไหน', 'สิทธิการรักษา, นักศึกษา, ตรวจสอบ', 'ตรวจสิทธิ์การรักษาพยาบาลนักศึกษา มข.', '1. ติดต่อขอตรวจสอบสิทธิที่ศูนย์สุขภาพนักศึกษา มข. (หลัง Complex) หรือศูนย์สุขภาพ 123 มข. (หลังหอ 8 หลัง)\n2. ตรวจสอบสิทธิด้วยตนเองผ่านระบบบริการออนไลน์\nลิงค์ : www.nhso.go.th', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (91, 10, 'จะย้ายสิทธิบัตรทองมา รพ.ศรีนครินทร์ต้องทำอย่างไร', 'ย้ายสิทธิบัตรทอง, รพ.ศรีนครินทร์', 'จะย้ายสิทธิบัตรทองมา รพ.ศรีนครินทร์ต้องทำอย่างไร', 'กรอกข้อมูลตามแบบฟอร์มขอย้ายสิทธิที่ศูนย์สุขภาพนักศึกษา (หลัง Complex) หรือศูนย์สุขภาพ 123 มข. (หลังหอ 8 หลัง) ในวัน เวลา ที่ศูนย์สุขภาพเปิดทำการ', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (92, 10, 'กรณีไม่ได้ย้ายสิทธิรักษาพยาบาลมาที่ รพ.ศรีนครินทร์จะต้องทำอย่างไร', 'ย้ายสิทธิรักษาพยาบาล, รพ.ศรีนครินทร์', 'กรณีไม่ได้ย้ายสิทธิมารักษาที่ รพ.ศรีนรินทร์', 'นักศึกษาต้องจ่ายค่ารักษาพยาบาลเองทั้งหมด \nลิงค์ : https://www.facebook.com/profile.php?id=61563625470249&locale=th_TH', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (93, 10, 'กรณีบาดเจ็บจากอุบัติเหตุจราจร', 'บาดเจ็บ, อุบัติเหตุจราจร', 'กรณีบาดเจ็บจากอุบัติเหตุจราจร', '1. ตรวจสอบว่าได้รถได้ต่อ พรบ.หรือไม่ หากได้ต่อ พรบ. ค่ารักษาพยาบาล 30,000 บาทแรกเบิกจาก พรบ. โดยเอาเอกสารต่อ พรบ.พร้อมสำเนาบัตรประชาชน ใบลงบันทึกประจำวันของตำรวจแนบให้พยาบาลไปดำเนินการ ส่วนค่าใช้จ่ายเกินจาก 30,000 จะนำไปเบิกจากสิทธิบัตรทองหรือสิทธิที่นักศึกษามี\n2. กรณีไม่มี พรบ. ค่ารักษาพยาบาลทั้งหมดนักศึกษาต้องจ่ายเอง ยกเว้นกรณีนักศึกษาไม่ผิด คู่กรณีผิดและคู่กรณีมี พรบ. ให้ใช้ พรบ.ของคู่กรณี\nลิงค์ :  https://www.facebook.com/profile.php?id=61563625470249&locale=th_TH', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (94, 10, 'นักศึกษาต่างชาติเจ็บป่วยต้องทำอย่างไร', 'นักศึกษาต่างชาติ, เจ็บป่วย', 'นักศึกษาต่างชาติเจ็บป่วยต้องทำอย่างไร', 'นักศึกษาต้่างชาติที่มีรหัสนักศึกษาที่ขึ้นต้นด้วย 57,58.... เป็นต้นไป ให้ทำประกันสุขภาพและจ่ายค่ารักษา และนำใบเสร็จไปเบิกจากบริษัทที่ทำประกันสุขภาพ\nลิงค์ :  https://www.facebook.com/profile.php?id=61563625470249&locale=th_TH', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (95, 10, 'สิทธิการักษาทันตกรรม', 'สิทธิการรักษา, ทันตกรรม', 'สิทธิการักษาทันตกรรม', '1. ใช้สิทธิบัตรทอง รพ.ศรีนคิรนทร์\n2.มีปัญหาเรืองช่องปากและฟัน - นักศึกษาสิทธิบัตรทองโรงพยาบาลศรีนครินทร์รับบริการได้ทีห้องตรวจทันตกรรมคณะทันตแพทยศาสตร์\nลิงค์ : https://dentistry.kku.ac.th/forpatient/%e0%b8%aa%e0%b8%b4%e0%b8%97%e0%b8%98%e0%b8%b4%e0%b9%8c%e0%b8%81%e0%b8%b2%e0%b8%a3%e0%b8%a3%e0%b8%b1%e0%b8%81%e0%b8%a9%e0%b8%b2', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (96, 10, 'มีปัญหาการเรียน ชีวิต การเงิน ติดต่อใครได้บ้าง', 'ปัญหาการเรียน, ชีวิต, การเงิน, ติดต่อ', 'มีปัญหาการเรียน ชีวิต การเงิน ติดต่อใครได้บ้าง', '1. ติดต่ออาจารย์ที่ปรึกษา อาจารย์ฝ่ายพัฒนานักศึกษาสาขาวิชาที่ตนเองสังกัด\n2. ติดต่อห้อง 6105 อาคาร SC06 กลุ่มภาระงานด้านพัฒนานักศึกษา', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (97, 10, 'มีปัญหาสุขภาพจิตปรึกษาใครได้บ้าง', 'ปัญหาสุขภาพจิต, ปรึกษา', 'มีปัญหาสุขภาพจิตติดต่อใครได้บ้าง', '1. ติดต่ออาจารย์ที่ปรึกษา อาจารย์ฝ่ายพัฒนานักศึกษาสาขาวิชาที่ตนเองสังกัด\n2. ติดต่อห้อง 6105 อาคาร SC06 กลุ่มภาระงานด้านพัฒนานักศึกษา\n3. ศูนย์ให้คำปรึกษาและแนะแนว (KKU MORE CARE)\n4. รพ.ศรีครินทร์ (แผนกจิตเวช )ห้องตรวจเบอร์ 7\nยื่นบัตรได้ตั้งแต่เวลา 07.00-11.00 น. ยกเว้นวันพุธ\n043-363001/043-363004\nลิงค์ : https://sac.kku.ac.th/%E0%B8%9A%E0%B8%A3%E0%B8%B4%E0%B8%81%E0%B8%B2%E0%B8%A3%E0%B9%83%E0%B8%AB%E0%B9%89%E0%B8%84%E0%B8%B3%E0%B8%9B%E0%B8%A3%E0%B8%B6%E0%B8%81%E0%B8%A9%E0%B8%B2', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (98, 10, 'คณะวิทยาศาสตร์มีอุปกรณ์การเรียนอะไรให้ยืมได้บ้าง', 'คณะวิทยาศาสตร์, อุปกรณ์การเรียน, ยืม', 'มีบริการให้ยืมอุปกรณ์การเรียนอะไรบ้าง', 'มีบริการให้ยืม Notebook \nติดต่อกลุ่มภาระงานด้านพัฒนานักศึกษา ห้อง 6105 อาคาร SC.06 (กำลังอยู่ระหว่างการทำระบบยืม-คืน notebook)', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (99, 11, 'กิจกรรมเสริมทักษะของคณะวิทยาศาสตร์มีอะไรบ้าง', 'กิจกรรมเสริมทักษะ, คณะวิทยาศาสตร์', 'เสริมทักษะ,LAB โรงเรียน', 'สวัสดีค่ะ รายละเอียดหัวข้อให้โรงเรียนเลือกนะคะ ขอรายชื่อนร. (Excel) จำนวนนร. ชื่อ-เบอร์โทรผู้ติดต่อ และ โปรดระบุวันที่ต้องการเข้าศึกษา Lab ค่ะ  https://sc.kku.ac.th/school-lab/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (100, 11, 'สอบถาม รายละเอียด เดี่ยวกับการอบรมเสริมความรู้ทักษะทางวิทย์', 'รายละเอียด, การอบรมเสริมความรู้, ทักษะทางวิทย์', 'รายละเอียดเสริมทักษะ,รายละเอียดLab โรงเรียน', 'สวัสดีค่ะ รายละเอียดหัวข้อให้โรงเรียนเลือกนะคะ ขอรายชื่อนร. (Excel) จำนวนนร. ชื่อ-เบอร์โทรผู้ติดต่อ และ โปรดระบุวันที่ต้องการเข้าศึกษา Lab ค่ะ  https://sc.kku.ac.th/school-lab/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (101, 11, 'ข้อมูลในการนำนักเรียนไปทำ lab วิทยาศาสตร์', 'ข้อมูล, นำนักเรียน, lab วิทยาศาสตร์', 'ข้อมูลในการนำนักเรียนไปทำ lab', 'สวัสดีค่ะ รายละเอียดหัวข้อให้โรงเรียนเลือกนะคะ ขอรายชื่อนร. (Excel) จำนวนนร. ชื่อ-เบอร์โทรผู้ติดต่อ และ โปรดระบุวันที่ต้องการเข้าศึกษา Lab ค่ะ  https://sc.kku.ac.th/school-lab/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (102, 11, 'อยากสอบถามเรื่องการทำแลป', 'การทำแลป', 'เสริมทักษะ,LAB โรงเรียน', 'สวัสดีค่ะ รายละเอียดหัวข้อให้โรงเรียนเลือกนะคะ ขอรายชื่อนร. (Excel) จำนวนนร. ชื่อ-เบอร์โทรผู้ติดต่อ และ โปรดระบุวันที่ต้องการเข้าศึกษา Lab ค่ะ  https://sc.kku.ac.th/school-lab/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (103, 11, 'บริการวิจัย', 'บริการวิจัย', 'บริการวิจัย', 'ติดต่อคุณจุฬาลักษณ์ โพธิชัย\nโทร. 44475 / 0956530131\nE-Mail : julpho@kku.ac.th', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (104, 11, 'พอดีว่ากำลังหาเชื้อไปทำการวิจัยครับ YSC ครับขอสอบถามเรื่องเชื้อหน่อยนะครับ ไม่ทราบว่ามีเชื้อ Propionibacterium acnes, Staphylococcus aureus และ Staphylococcus epidermidis ไหมครับ', 'เชื้อ, การวิจัย, Propionibacterium acnes, Staphylococcus aureus, Staphylococcus epidermidis', 'ถามเรื่องเชื้อ,เชื้อไปทำการวิจัย', 'แนะนำติดต่อสอบถามไปที่สาขาวิชาจุลชีววิทยา ที่เพจ https://www.facebook.com/scmicrokku นะคะ', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (105, 12, 'ติดต่อขอใช้บริการเครื่องมือวิทยาศาสตร์', 'ติดต่อ, บริการเครื่องมือวิทยาศาสตร์', 'เครื่องมือวิทยาศาสตร์', 'สามารถดูข้อมูลเพิ่มเติมได้ที่ https://ci.sc.kku.ac.th/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (106, 12, 'ต้องการส่งตัวอย่างวิเคราะห์', 'ส่งตัวอย่าง, วิเคราะห์', 'ตัวอย่างวิเคราะห์', 'ติดต่อคุณจิราภรณ์ พิมพ์ภูมี โทร. 082-3235875 E-mail: jirpim@kku.ac.th หรือดูข้อมูลเพิ่มเติมได้ที่ https://ci.sc.kku.ac.th/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (107, 13, 'สนใจส่งบทความมาตีพิมพ์ในวารสารวิทยาศาสตร์ มข.', 'ส่งบทความ, วารสารวิทยาศาสตร์ มข.', 'วารสารวิทยาศาสตร์ มข.', 'วารสารวิทยาศาสตร์ มข. (KKU SCIENCE JOURNAL)\nISSN: 3027-6667 (Online)\nได้รับการรับรองคุณภาพวารสาร จัดอยู่ในวารสารกลุ่มที่ 1 จากศูนย์ดัชนีการอ้างอิงวารสารไทย (Thai Journal Citation Index Centre: TCI) พ.ศ. 2568 - 2572\n\nโดยเปิดรับบทความวิชาการในกลุ่มสาขาวิทยาศาสตร์  คณิตศาสตร์ เทคโนโลยีสารสนเทศ และวิทยาการคณนา แะแบ่งประเภทของงานเป็น 2 ประเภท คือ บทความวิจัย และบทความวิชาการ มีกำหนดเผยแพร่ 3 ฉบับต่อปี คือ ฉบับที่ 1: มกราคม - เมษายน ฉบับที่ 2: พฤษภาคม - สิงหาคม ฉบับที่ 3: กันยายน - ธันวาคม\n\nสามารถส่งบทความตีพิมพ์ได้ที่: https://ph01.tci-thaijo.org/index.php/KKUSciJ\n\nติดต่อสอบถามเพิ่มเติม : คุณศิรประภา  หงษ์ชัยภูมิ\nเบอร์โทร 043-009700 ต่อ 44886, มือถือ 095-6720846\nE-mail: kku_scijournal@kku.ac.th', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (108, 14, 'จะดาวน์โหลดเกียรติบัตรได้เมื่อไหร่ และดาวน์โหลดจากที่ไหน?', 'ดาวน์โหลดเกียรติบัตร,downloadเกียรติบัตร', 'ดาวน์โหลดเกียรติบัตร,เวลาออกเกียรติบัตร,ช่องทางดาวน์โหลด', 'เกียรติบัตรสามารถดาวน์โหลดได้ที่เมนู \'เกียรติบัตร\' บนเว็บไซต์งานสัปดาห์วิทยาศาสตร์ของคณะวิทยาศาสตร์ มข. (https://www.sc.kku.ac.th/scweek) หรือลิงก์ระบบเกียรติบัตร https://apps.sc.kku.ac.th/scweek/competition/index.php?r=cert โดยปกติจะเปิดให้ดาวน์โหลดหลังวันที่ 20 (ส.ค.) เมื่อทีมเลขาแต่ละกิจกรรมตรวจสอบข้อมูลเรียบร้อยแล้ว หากยังหาไม่เจอ กรุณาติดต่อฝ่ายประสานงานเพื่อขอความช่วยเหลือ\nลิงค์ : https://www.sc.kku.ac.th/scweek\nhttps://apps.sc.kku.ac.th/scweek/competition/index.php?r=cert', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (109, 14, 'ชื่อบนเกียรติบัตรผิด ต้องแก้ยังไง?', 'ชื่อบนเกียรติบัตร, แก้ไข,เกียรติบัตรผิด', 'แก้ชื่อเกียรติบัตร,ติดต่อแก้ไขชื่อ', 'ส่งข้อมูลขอแก้ไขไปยังฝ่ายประสานงานเกียรติบัตร ดังนี้: \n1) ระบุชื่อกิจกรรม \n2) ประเภทผู้เข้าแข่งขัน (ครู/นักเรียน) \n3) ชื่อเดิม \n4) ชื่อที่ต้องการแก้ไข ส่งไปที่ e-mail: jaroonluk@kku.ac.th เจ้าหน้าที่จะตรวจสอบและแก้ไขให้ตามกระบวนการ', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (110, 14, 'โล่รางวัล/ของรางวัลจะจัดส่งหรือรับได้ที่ไหน?', 'โล่รางวัล, ของรางวัล, จัดส่ง, รับ', 'รับโล่รางวัล,การจัดส่งรางวัล,ติดต่อรับรางวัล', 'การรับโล่รางวัลหรือของรางวัลจะแจ้งให้ทราบผ่านช่องทางการประกาศอย่างเป็นทางการ (เพจ Facebook และเว็บไซต์งาน) ฝ่ายจัดจะประสานกับผู้ได้รับรางวัลเพื่อจัดส่งหรือกำหนดการรับ หากท่านเป็นผู้ได้รับรางวัลและยังไม่ได้รับการติดต่อ โปรดแจ้งผ่านเพจหรืออีเมลฝ่ายจัดกิจกรรมเพื่อทราบข้อมูลเพิ่มเติม\nลิงค์ : https://www.facebook.com/KKUScienceWeek\n https://www.sc.kku.ac.th/scweek', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (111, 14, 'กิจกรรม \'ทักษะการแก้ปัญหาทางวิทยาศาสตร์\' คืออะไรและเตรียมตัวอย่างไร?', 'กิจกรรม, ทักษะการแก้ปัญหาทางวิทยาศาสตร์, เตรียมตัว', 'ทักษะแก้ปัญหา,การเตรียมตัว,วิธีฝึก', 'กิจกรรมนี้เป็นการแข่งขันทดสอบทักษะการออกแบบและแก้ปัญหาทางวิทยาศาสตร์ ผู้เข้าแข่งขันควรฝึกการคิดวิเคราะห์ ทดลองและอธิบายวิธีคิด  และอ่านคู่มือการแข่งขันที่จัดส่งหรือเผยแพร่บนเว็บไซต์งาน หากมีข้อสงสัยด้านกติกา ให้ติดต่อฝ่ายจัดกิจกรรมก่อนวันแข่งขัน\nลิงค์ : https://apps.sc.kku.ac.th/scweek/, https://www.facebook.com/KKUScienceWeek', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (112, 14, 'การแข่งขันกระบวนการแก้ปัญหาทางคณิตศาสตร์ แข่งวันไหน และเผยแพร่โจทย์ไหม?', 'การแข่งขัน, กระบวนการแก้ปัญหาทางคณิตศาสตร์, วันแข่ง, เผยแพร่โจทย์', 'ตารางแข่งขันคณิตศาสตร์,เผยแพร่โจทย์', 'กำหนดการแข่งขันสามารถดูได้จากตารางกิจกรรมบนเว็บไซต์และเพจอย่างเป็นทางการ (https://apps.sc.kku.ac.th/scweek/ และ Facebook/KKUScienceWeek) ส่วนการเผยแพร่โจทย์: ทีมผู้จัดจะไม่เผยแพร่โจทย์การแข่งขัน (ตามนโยบายที่ผ่านมา) หากต้องการฝึก ให้เตรียมแบบฝึกหัดการคิดเชิงเหตุผลและกระบวนการทางคณิตศาสตร์ทั่วไป\nลิงค์ : https://apps.sc.kku.ac.th/scweek/, https://www.facebook.com/KKUScienceWeek', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (113, 14, 'โครงงานที่ผ่านเข้ารอบต้องไปจัดบูธกี่วัน และกรรมการตรวจอย่างไร?', 'โครงงาน, เข้ารอบ, จัดบูธ, กรรมการตรวจ', 'จัดบูธกี่วัน, โครงงานเข้ารอบ, กรรมการตรวจ, จำนวนวันจัดบูธ,จัดบูธ', 'โครงงานที่เข้ารอบจะต้องจัดแสดงผลงานตามวันที่กำหนด (โดยทั่วไปคือ 3 วันของการแข่งขัน) ผู้เข้าแข่งขันควรสแตนด์บายที่บูธตลอดเวลาที่จัดแสดงเพราะกรรมการจะเวียนมาตรวจตามรอบเวลา ไม่มีการระบุเวลาเรียงทีมตายตัว หากมีกรณีสมาชิกขาดบางวัน ให้แจ้งเหตุผลและการตัดสินขึ้นกับดุลยพินิจของคณะกรรมการ\nลิงค์ : https://apps.sc.kku.ac.th/scweek/, https://www.facebook.com/KKUScienceWeek', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (114, 14, 'การส่งเล่ม/รูปเล่มโครงงานต้องเป็นอย่างไร (จำนวนหน้า/รูปแบบ)?', 'ส่งเล่ม, รูปเล่ม, โครงงาน, จำนวนหน้า, รูปแบบ', 'รูปเล่มโครงงาน,จำนวนหน้า,เงื่อนไขส่งเล่ม', 'รูปเล่มฉบับสมบูรณ์สำหรับส่งเจ้าหน้าที่ควรมีเนื้อหาครบถ้วน แต่งเล่มที่ใช้ในการประกวด (เช่นรูปเล่มสำหรับกรรมการ) ตามประกาศทั่วไปกำหนดไม่เกิน 15 หน้าสำหรับบางรอบ แต่ฉบับสมบูรณ์ที่ส่งอาจไม่จำกัดหน้า (โปรดตรวจประกาศของแต่ละรอบ) หากกติการะบุไว้ชัดเจน ให้ถือกติกานั้นเป็นหลัก\nลิงค์ : https://apps.sc.kku.ac.th/scweek/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (115, 14, 'ถ้ามีสมาชิกทีมไม่ครบ สามารถแข่งขันได้ไหม?', 'สมาชิกทีม, ไม่ครบ, แข่งขัน', 'สมาชิกไม่ครบ,เปลี่ยนผู้เข้าแข่งขัน,การพิจารณา', 'กรณีสมาชิกขาด ให้แจ้งเหตุผลต่อคณะกรรมการ ณ วันแข่ง การตัดสินว่าจะให้แข่งขันหรือไม่ขึ้นกับดุลยพินิจของกรรมการ แต่โดยทั่วไปสามารถนำเสนอโดยสมาชิกที่เหลือได้ (เช่น 2 คน จาก 3 คน)\nลิงค์ : https://apps.sc.kku.ac.th/scweek/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (116, 14, 'การแข่งขันตอบปัญหาต้องมาลงทะเบียนกี่โมง? ต้องมาพร้อมทีมหรือไม่?', 'การแข่งขันตอบปัญหา, ลงทะเบียน, พร้อมทีม', 'เวลาลงทะเบียนตอบปัญหา,เปลี่ยนตัวผู้เข้าแข่งขัน,จำนวนผู้เข้าแข่งขัน', 'ผู้แข่งขันควรมาลงทะเบียนก่อนเวลาที่กำหนดอย่างน้อย 30 นาที (แนะนำมาล่วงหน้า) หากทีมมาน้อยกว่าจำนวนที่ระบุ อาจไม่ได้รับอนุญาตให้แข่งขันตามกติกา (เช่นมาไม่ครบตามเงื่อนไขจะถูกตัดสิทธิ) การเปลี่ยนตัวผู้เข้าแข่งขันสามารถทำได้ที่วันรายงานตัวก่อนเริ่มการแข่งขันเท่านั้น\nลิงค์ : https://www.facebook.com/KKUScienceWeek, https://apps.sc.kku.ac.th/scweek/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (117, 14, 'สถานที่/อาคารของการแข่งขันตอบปัญหาคือที่ไหน?', 'สถานที่, อาคาร, การแข่งขันตอบปัญหา', 'สถานที่ตอบปัญหา,ห้องแข่งขัน', 'สถานที่แข่งขันแจ้งไว้ในตารางและประกาศอย่างเป็นทางการ เช่น รายการตอบปัญหาระดับ ม.ปลาย จัดที่ ห้อง 3201 (ชั้น 2) อาคาร SC.03 คณะวิทยาศาสตร์ มข. กรุณาตรวจสอบแผนที่และประกาศหน้ากิจกรรมบนเพจก่อนวันแข่งขัน\nลิงค์ : https://www.facebook.com/KKUScienceWeek', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (118, 14, 'จะทราบผล/ประกาศผลการแข่งขันวาดภาพและติดตามได้ที่ไหน?', 'ผลการแข่งขัน, วาดภาพ, ประกาศผล, ติดตาม', 'ผลประกวดวาดภาพ,ประกาศผล,เกียรติบัตร', 'ผลและประกาศรางวัลของการประกวดวาดภาพจะประกาศผ่านเว็บไซต์และเพจอย่างเป็นทางการ (Facebook/KKUScienceWeek และเว็บไซต์งาน) หากมีเกียรติบัตรสำหรับผู้เข้าร่วม จะสามารถดาวน์โหลดตามช่องทางเดียวกับกิจกรรมอื่น ๆ\nลิงค์ : https://www.facebook.com/KKUScienceWeek, https://apps.sc.kku.ac.th/scweek/', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (119, 14, 'สื่อการสอนสำหรับครูส่งที่ไหนและมีการประกาศผลอย่างไร?', 'สื่อการสอน, สำหรับครู, ส่ง, ประกาศผล', 'ส่งสื่อการสอน,ประกาศผลสื่อครู,ดาวน์โหลดเกียรติบัตรครู', 'การส่งผลงานและการประกาศผลตรวจสอบที่ระบบลงทะเบียน/เว็บไซต์งาน หากได้รับรางวัล เจ้าหน้าที่จะแจ้งผู้ได้รับรางวัลและวิธีรับรางวัลผ่านประกาศอย่างเป็นทางการ สามารถตรวจสอบรายชื่อผู้เข้าสอบและผลได้ทาง https://apps.sc.kku.ac.th/scweek/ และเพจ Facebook\nลิงค์ : https://apps.sc.kku.ac.th/scweek/, https://www.facebook.com/KKUScienceWeek', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (120, 14, 'ถ้าส่งผลงานแล้วยังไม่เห็นเกียรติบัตร ต้องทำอย่างไร?', 'ส่งผลงาน, เกียรติบัตร', 'เกียรติบัตรสื่อครู,ดาวน์โหลดเกียรติบัตร', 'เกียรติบัตรจะเปิดให้ดาวน์โหลดหลังทีมเลขาตรวจสอบข้อมูลผู้เข้าร่วมเรียบร้อยแล้ว หากผลงานหรือชื่อไม่มีในระบบ ให้แจ้งรายละเอียด (ชื่อผู้ส่ง, โรงเรียน, ชื่อผลงาน) ให้เจ้าหน้าที่ตรวจสอบผ่านช่องทางที่ระบุบนเว็บไซต์หรือเพจ\nลิงค์ : https://apps.sc.kku.ac.th/scweek/competition/index.php?r=cert', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (121, 14, 'การสื่อสารทางวิทยาศาสตร์ (Science Communication) มีรูปแบบใดบ้างและจะประกวดอย่างไร?', 'การสื่อสารทางวิทยาศาสตร์, รูปแบบ, ประกวด,สื่อสารวิทย์', 'การสื่อสารวิทย์,รูปแบบประกวด,เกณฑ์ตัดสิน', 'การสื่อสารทางวิทยาศาสตร์เป็นกิจกรรมที่เน้นการนำเสนอความรู้วิทยาศาสตร์แก่สาธารณะ เช่น การพูดนำเสนอ, วิดีโอ, โปสเตอร์หรือสื่อใหม่ ๆ กติกาและรูปแบบการประกวดจะระบุในประกาศกิจกรรม โปรดตรวจสอบรายละเอียดการส่งผลงานและเกณฑ์การตัดสินในเพจหรือระบบสมัคร\nลิงค์ : https://apps.sc.kku.ac.th/scweek/, https://www.facebook.com/KKUScienceWeek', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (122, 14, 'Science Show มีอุปกรณ์ให้หรือไม่ ต้องเตรียมอะไรบ้าง?', 'Science Show, อุปกรณ์, เตรียม', 'อุปกรณ์ Science Show,เตรียมอุปกรณ์,ไฟล์เสียง', 'ศูนย์จัดเตรียมอุปกรณ์พื้นฐานและนักศึกษาช่วยงานบางส่วนไว้ แต่ผู้เข้าร่วมควรเตรียมอุปกรณ์หลักของการแสดง/สื่อตามที่ออกแบบไว้ หากมีไฟล์เสียง/วิดีโอ ให้ส่งหรือแจ้งฝ่ายจัดล่วงหน้าตามคำแนะนำ กรณีต้องการให้ผู้ติดตามช่วยจัดอุปกรณ์ สามารถทำได้ตามข้อกำหนดเวลาในการติดตั้งและเก็บของที่แจ้งไว้\nลิงค์ : https://www.facebook.com/KKUScienceWeek', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (123, 14, 'ผลการแข่งขันจรวดขวดน้ำ/ดูผลได้ที่ไหน?', 'ผลการแข่งขัน, จรวดขวดน้ำ, ดูผล', 'จรวดขวดน้ำ ผลการแข่งขัน,ประกาศผล', 'ผลการแข่งขันและรายละเอียดตรวจสอบได้จากประกาศของฝ่ายจัดกิจกรรมบนเพจหรือเว็บไซต์งาน หากมีไฟล์ผลหรือภาพกิจกรรมจะแจ้งลิงก์เผยแพร่ เช่น โพสต์ที่เกี่ยวข้องใน Facebook หรือพื้นที่เก็บไฟล์ของคณะ\nลิงค์ : https://www.facebook.com/KKUScienceWeek, https://www.facebook.com/share/16pwt9rsZZ/?mibextid=wwXIfr', '2026-08-16 16:30:32', '2026-08-16 16:30:32');
INSERT INTO `faqs` VALUES (124, 14, 'แข่งเครื่องบินกระดาษต้องลงทะเบียนยังไง และมาช่วงไหนได้บ้าง?', 'แข่งเครื่องบินกระดาษ, ลงทะเบียน, มาช่วงไหน', 'เครื่องบินกระดาษ ลงทะเบียน,เวลาการแข่งขัน', 'รายละเอียดการลงทะเบียนและเวลาการแข่งขันของเครื่องบินกระดาษจะประกาศในเว็บไซต์และคู่มือกิจกรรม บางปีสามารถลงทะเบียนมารายงานตัวได้ทั้งสองวันตามที่กำหนด โปรดตรวจสอบข้อกำหนดในประกาศหรือบนหน้าเว็บที่เกี่ยวข้อง (ตัวอย่างแหล่งข้อมูล: https://www.mtec.or.th/paperairplane/)\nลิงค์ : https://www.mtec.or.th/paperairplane/, https://apps.sc.kku.ac.th/scweek/', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (125, 14, 'จะขอดูกำหนดการเต็มของงานได้จากที่ไหน?', 'กำหนดการเต็ม, งาน,กำหนดการ', 'กำหนดการ,ตารางกิจกรรม,ประกาศกำหนดการ', 'ตารางกำหนดการแข่งขันและกิจกรรมทั้งหมดประกาศบนหน้าเว็บไซต์งานและเพจเฟซบุ๊กของสัปดาห์วิทยาศาสตร์คณะวิทยาศาสตร์ มข. ตรวจสอบได้ที่ https://apps.sc.kku.ac.th/scweek/ และ https://www.facebook.com/KKUScienceWeek หากต้องการเอกสารกำหนดการแบบละเอียด ให้ติดตามการประกาศช่วงต้นเดือนสิงหาคมหรือขอสำเนาจากฝ่ายประชาสัมพันธ์\nลิงค์ : https://apps.sc.kku.ac.th/scweek/, https://www.facebook.com/KKUScienceWeek', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (126, 14, 'มีตารางการแข่งขันแยกตามกิจกรรมไหม ตรวจสอบได้ที่ไหน?', 'ตารางการแข่งขัน, แยกตามกิจกรรม, ตรวจสอบ', 'ตารางกิจกรรม,ตารางการแข่งขัน,ตรวจสอบตาราง', 'ตารางการแข่งขันสำหรับแต่ละกิจกรรมมีเผยแพร่บนเว็บไซต์งานและเพจ Facebook อย่างเป็นทางการ สามารถตรวจสอบตารางและสถานที่แข่งขันได้ที่ https://apps.sc.kku.ac.th/scweek/ และ https://www.facebook.com/KKUScienceWeek หากต้องการข้อมูลเฉพาะกิจกรรม โปรดแจ้งชื่อกิจกรรมเพื่อผมช่วยค้นให้\nลิงค์ : https://apps.sc.kku.ac.th/scweek/, https://www.facebook.com/KKUScienceWeek', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (127, 14, 'เปิดรับสมัครร้านค้าในงานไหม', 'เปิดรับสมัคร, ร้านค้า, งาน', 'ร้านค้า,เปิดรับสมัครร้านขายของ,ร้านขายของ', 'หากมีการเปิดรับสมัคร จะประชาสัมพันธ์ผ่าน https://www.facebook.com/KKUScienceWeek หากต้องการเอกสารกำหนดการแบบละเอียด ให้ติดตามการประกาศช่วงต้นเดือนสิงหาคมหรือขอสำเนาจากฝ่ายประชาสัมพันธ์\nลิงค์ : https://www.facebook.com/KKUScienceWeek', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (128, 15, 'ถ้าอยากสมัครเรียน scius วมว.มข ต้องทำอย่างไร', 'สมัครเรียน, scius, วมว.มข', 'สมัครเรียน', 'โครงการ วมว.-มข. รับสมัครนักเรียนระดับชั้น ม.3 เพื่อสอบเข้าเรียนต่อในระดับชั้น ม.4 โดยช่วงที่เปิดรับสมัครจะอยู่ในช่วงวันที่ 1-31 สิงหาคม ของทุกปี', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (129, 15, 'ต้องมีคุณสมบัติอย่างไรในการสมัครสอบ scius วมว.มข', 'คุณสมบัติ, สมัครสอบ, scius, วมว.มข', 'คุณสมบัติ, เงื่อนไขการสมัคร', 'กำลังศึกษาอยู่ในชั้นปีสุดท้ายของหลักสูตรมัธยมศึกษาตอนต้น ประจำปีการศึกษา 2567 ตามหลักสูตรแกนกลางการศึกษาขั้นพื้นฐาน พุธศักราช 2551 (ฉบับปรับปรุงพุทธศักราช 2560) ของกระทรวงศึกษาธิการ หรือหลักสูตรอื่นที่กระทรวงศึกษาธิการรับรองว่าเทียบเท่า\n มีผลการเรียน ดังนี้\n 1.ระดับคะแนนเฉลี่ยสะสมรวมทุกรายวิชาในชั้นมัธยมศึกษาปีที่ 1 และ 2 ไม่ต่ำกว่า 3.00\n 2.ระดับคะแนนเฉลี่ยสะสมกลุ่มสาระการเรียนรู้วิทยาศาสตร์ในชั้นมัธยมศึกษาปีที่ 1 และ 2 ไม่ต่ำกว่า 3.00\n 3.ระดับคะแนนเฉลี่ยสะสมกลุ่มสาระการเรียนรู้วิชาคณิตศาสตร์ในชั้นมัธยมศึกษาปีที่ 1 และ 2 ไม่ต่ำกว่า 3.00\n 4.มีสัญชาติไทย (มีเลขประจำตัวประชาชน)\n 5.ไม่เป็นโรคติดต่อร้ายแรงซึ่งเป็นอุปสรรคต่อการศึกษา และการพักในโรงเรียนหรือสถานที่ที่โรงเรียนจัดไว้ให้ในลักษณะโรงเรียนประจำ\n 6.สามารถพักอยู่ในโรงเรียนหรือสถานที่ที่โรงเรียนจัดไว้ให้ในลักษณะโรงเรียนประจำได้ และ7.สามารถปฏิบัติตามกฎระเบียบที่โรงเรียนกำหนด\n 8.มีความขยันหมั่นเพียร มีความประพฤติดีและมีบุคลิกภาพเหมาะสม\n 9.มีความตั้งใจเข้าเรียนในโรงเรียนในโครงการ วมว. และสนใจศึกษาต่อระดับอุดมศึกษาด้านคณิตศาสตร์ วิทยาศาสตร์และเทคโนโลยี รวมถึงได้รับการสนับสนุนจากผู้ปกครอง\nลิงค์ : https://scius.mhesi.go.th/index.php/th/aboutus/history.html', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (130, 15, 'scius วมว.มข สามารถสมัครได้ช่องทางไหน', 'scius, วมว.มข, สมัคร, ช่องทาง', 'ช่องทาง, สมัครที่ไหน', 'สามารถสมัครได้ทาง https://apply.mwit.ac.th/\n โดยระยะเวลารับสมัครจะอยู่ในช่วงวันที่ 1-31 สิงหาคม ของทุกปี\nลิงค์ : https://apply.mwit.ac.th/', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (131, 15, 'สนใจสมัครสอบ scius วมว.มข', 'สนใจสมัครสอบ, scius, วมว.มข', 'สมัครสอบ', 'สามารถสมัครได้ทาง https://apply.mwit.ac.th/\n โดยระยะเวลารับสมัครจะอยู่ในช่วงวันที่ 1-31 สิงหาคม ของทุกปี\nลิงค์ : https://apply.mwit.ac.th/', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (132, 15, 'scius วมว.มข  ต้องสอบวิชาอะไรบ้าง', 'scius, วมว.มข, สอบวิชา', 'วิชาสอบ, วิชาอะไร, สอบอะไร', 'เนื้อหาในการสอบจะครอบคลุมสาระวิชาคณิตศาสตร์และวิทยาศาสตร์ ระดับชั้นมัธยมศึกษาตอนต้น\n ตามหลักสูตรแกนกลาง ตามหัวข้อ ดังนี้\n คณิตศาสตร์\n วิทยาศาสตร์ (ฟิสิกส์ เคมี ชีววิทยา)\n วิชาเทคโนโลยี\n ภาษาอังกฤษ\nลิงค์ : https://scius.kku.ac.th/?page_id=1730', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (133, 15, 'scius วมว.มข   ค่าใช้จ่าย ค่าเทอม เท่าไหร่', 'scius, วมว.มข, ค่าใช้จ่าย, ค่าเทอม', 'ค่าใช้จ่าย, ค่าเทอม', 'โครงการ วมว.-มข. สนับสนุนค่าใช้จ่ายเกี่ยวกับการศึกษาของนักเรียนในโครงการ ได้แก่ ค่าธรรมเนียมการศึกษา ค่าหนังสือ เอกสารประกอบการเรียน กิจกรรมพัฒนาผู้เรียนที่จัดโดยโครงการ ค่าหอพัก รวมถึงค่าอาหารในวันที่มีการเรียนการสอน', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (134, 15, 'scius วมว.มข ให้ทุนยังไง', 'scius, วมว.มข, ให้ทุน', 'ทุน', 'ทุนที่ได้รับโครงการ วมว.-มข.นำมาบริหารจัดการสนับสนุนค่าใช้จ่ายเกี่ยวกับการศึกษาของนักเรียนในโครงการ ได้แก่ ค่าธรรมเนียมการศึกษา ค่าหนังสือ เอกสารประกอบการเรียน กิจกรรมพัฒนาผู้เรียนที่จัดโดยโครงการ ค่าหอพัก รวมถึงค่าอาหารในวันที่มีการเรียนการสอน', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (135, 15, 'scius วมว.มข ต้องคืนทุนไหม', 'scius, วมว.มข, คืนทุน', 'คืนทุน', 'เป็นทุนสนับสนุนให้ผู้เรียนโดยไม่ต้องคืนทุน', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (136, 15, 'scius วมว.มข มีการบังคับให้เรียนต่อทางวิทยาศาสตร์เท่านั้นหรือไม่', 'scius, วมว.มข, บังคับ, เรียนต่อ, วิทยาศาสตร์', 'เรียนต่อ', 'ไม่ได้บังคับสายวิชาในการศึกษาต่อ นักเรียนสามารถศึกษาต่อคณะที่ต้องการได้', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (137, 15, 'scius วมว.มข มีโควต้าคณะแพทยศาสตร์หรือไม่', 'scius, วมว.มข, โควต้า, คณะแพทยศาสตร์', 'แพทยศาสตร์', 'ไม่มี', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (138, 15, 'มีโควต้าเข้าศึกษาต่อระดับมหาวิทยาลัยสำหรับนักเรียนโครงการ วมว.-มข. หรือไม่', 'โควต้า, เข้าศึกษาต่อ, มหาวิทยาลัย, โครงการ วมว.-มข.', 'โควตา, ศึกษาต่อ, มหาวิทยาลัย', 'ปัจจุบันนี้มีคณะที่เกี่ยวกับวิทยาศาสตร์และเทคโนโลยี มีรอบการรับสมัครนักเรียนโควต้า วมว. เพื่อศึกษาต่อในหลายมหาวิทยาลัย\n ซึ่งนักเรียนต้องติดตามการศึกษาต่อเป็นประจำ \n ซึ่งคณะวิทยาศาสตร์ มหาวิทยาลัยขอนแก่น ก็มีทุนการศึกษาให้กับนักเรียนโครงการ วมว.-มข.', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (139, 15, 'คณะที่มีทุนการศึกษาให้นักเรียนโครงการ วมว.-มข. ศึกษาต่อระดับอุดมศึกษา', 'คณะ, ทุนการศึกษา, นักเรียนโครงการ วมว.-มข., ศึกษาต่อ, อุดมศึกษา', 'ศึกษาต่อ, อุดมศึกษา', 'ปัจจุบันนี้มีคณะที่เกี่ยวกับวิทยาศาสตร์และเทคโนโลยีให้ทุนการศึกษาหลายมหาวิทยาลัย\n ซึ่งนักเรียนต้องติดตามข่าวทุนการศึกษาเป็นประจำ', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (140, 15, 'scius วมว.มข  นักเรียนต้องอยู่หอพักไหม', 'scius, วมว.มข, นักเรียน, หอพัก', 'หอพัก', 'นักเรียนโครงการ วมว.-มข. จะต้องพักอาศัยอยู่ที่หอพักของโครงการในช่วงเปิดเรียน สามารถกลับบ้านได้ช่วงเสาร์อาทิตย์และวันหยุด ยกเว้นมีกิจกรรมที่จำเป็นต้องพักที่หอพัก', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (141, 15, 'scius วมว.มข หอพักเป็นแบบไหน', 'scius, วมว.มข, หอพัก, แบบ', 'ลักษณะหอพัก', 'หอพักนักเรียนโครงการ วมว.-มข. เป็นอาคารแยกชายหญิง พักอาศัยห้องละ 3 คน มีห้องน้ำในตัว โดยนักเรียนจำต้องช่วยกันดูแลความสะอาดภายในห้องของตนเอง\n มีสิ่งอำนวยความสะดวกในหอพักได้แก่ Wifi ห้องสมุด ห้องคอมพิวเตอร์ ห้องเอนกประสงค์ ห้องเลคเชอร์ ห้องกระจกซ้อมเต้น ห้องซ้อมดนตรี สนามกีฬา โรงอาหาร เครื่องซักผ้า', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (142, 15, 'scius วมว.มข นักเรียนเดินทางไปโรงเรียนอย่างไร', 'scius, วมว.มข, นักเรียน, เดินทาง, โรงเรียน', 'เดินทาง', 'นักเรียนโรงเรียนสาธิตมหาวิทยาลัยขอนแก่น ฝ่ายมัธยมศึกษา (ศึกษาศาสตร์) เดินทางโดยการเดินไปโรงเรียน ระยะทาง 500 เมตร ยกเว้นวันที่ฝนตกหนัก จะมีรถไปส่งที่โรงเรียน\n ส่วนนักเรียนโรงเรียนสาธิตมหาวิทยาลัยขอนแก่น ฝ่ายมัธยมศึกษา (มอดินแดง) เดินทางโดยรถบัสและรถหกล้อที่โครงการจัดให้', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (143, 15, 'scius วมว.มข ช่องทางติดต่อและสอบถามข้อมูลเพิ่มเติม', 'scius, วมว.มข, ช่องทางติดต่อ, ข้อมูลเพิ่มเติม', 'ติดต่อ, สอบถาม', 'ช่องทางการติดต่อ โครงการ วมว.-มข.\n ศูนย์บริหารจัดการห้องเรียนวิทยาศาสตร์ในโรงเรียน SCiUS-KKU\n ที่ตั้ง มหาวิทยาลัยขอนแก่น เลขที่ 123 ม.16 ต.ในเมือง อ.เมือง จ.ขอนแก่น 40002\n Website : https://scius.kku.ac.th/\n Facebook : https://www.facebook.com/sciuskku\n โทรศัพท์\n วมว.-มข. สำนักงาน คณะวิทยาศาสตร์ : 080-1816668\n วมว.-มข. โรงเรียนสาธิตฯ มอดินแดง : 099-2032111\n วมว.-มข. โรงเรียนสาธิตฯ ศึกษาศาสตร์ : 080-4010744\n หอพักต้นกล้ากัลปพฤกษ์ : 043-202658 , 099-2031333\n E-Mail : scius_kku@kku.ac.th', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (144, 1, 'ติดต่อ สอบถาม ข้อมูลคณะวิทยาศาสตร์ มหาวิทยาลัยขอนแก่น', 'ติดต่อ, สอบถาม, ข้อมูล, คณะวิทยาศาสตร์, มหาวิทยาลัยขอนแก่น', '', 'Facebook: Faculty of Science , Khon Kaen University - SCi KKU https://www.facebook.com/SCiKKU\nLINE Official Account  :  @320ceegz\nเว็บไซต์: https://sc.kku.ac.th/', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (145, 1, 'ข้อมูลทั่วไปคณะวิทยาศาสตร์', 'ข้อมูลทั่วไป, คณะวิทยาศาสตร์', '', 'ขออภัยค่ะ ข้อมูลส่วนนี้ไม่มีในระบบที่ตรวจสอบได้ในขณะนี้\nแนะนำให้ติดต่อเจ้าหน้าที่คณะวิทยาศาสตร์โดยตรง ได้ที่:\n📞 เบอร์โทร: 043-009-700\n• งานบริการการศึกษา 084-600-1149\n• งานบริการวิชาการและวิจัย ต่อ 44523\n• งานสารบรรณ ต่อ 44260\n• ฝ่ายประชาสัมพันธ์ ต่อ 42958\n📧 อีเมล: sc.inbox@kku.ac.th', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
INSERT INTO `faqs` VALUES (146, 1, '\"สวัสดี\", \"หวัดดี\", \"Hello\", \"Hi\" หรือสอบถามว่า \"คุณคือใคร\" ให้ตอบกลับอย่างสุภาพและเป็นมิตร เช่น \"สวัสดีค่ะ ยินดีต้อนรับสู่บริการตอบคำถามคณะวิทยาศาสตร์ มข. มีอะไรให้ช่วยตรวจสอบข้อมูลไหมคะ?\"', 'สวัสดี, หวัดดี, Hello, Hi, คุณคือใคร', 'สวัสดี\", \"หวัดดี\", \"Hello\", \"Hi\",คุณคือใคร', 'สวัสดีค่ะ ยินดีต้อนรับสู่บริการตอบคำถามคณะวิทยาศาสตร์ มข. มีอะไรให้ช่วยตรวจสอบข้อมูลไหมคะ?', '2026-08-16 16:30:33', '2026-08-16 16:30:33');
